import { SurveyBeatApi } from "@surveybeat/api";
import { Effect, Predicate, Schema } from "effect";
import { FetchHttpClient } from "effect/http";
import { HttpApiClient } from "effect/http-api";

/** Why an API call failed, as the screens explain it. */
export const Failure = Schema.Literals([
  "Unauthenticated",
  "Forbidden",
  "NotFound",
  "LastLead",
  "LastAdmin",
  "TeamNameTaken",
  "QuestionAlreadyInPulse",
  "QuestionHasAnswers",
  "PulseNeedsAQuestion",
  "PulseFull",
  "OrderMismatch",
  "Invalid",
  "Unavailable",
]);
export type Failure = typeof Failure.Type;

const NOT_FOUND = ["TeamNotFound", "PersonNotFound", "PulseNotFound", "QuestionNotFound"] as const;
const AS_IS = [
  "Unauthenticated",
  "Forbidden",
  "LastLead",
  "LastAdmin",
  "TeamNameTaken",
  "QuestionAlreadyInPulse",
  "QuestionHasAnswers",
  "PulseNeedsAQuestion",
  "PulseFull",
  "OrderMismatch",
] as const;

const failureOf = (error: unknown): Failure => {
  for (const tag of AS_IS) if (Predicate.isTagged(error, tag)) return tag;
  if (NOT_FOUND.some((tag) => Predicate.isTagged(error, tag))) return "NotFound";
  if (Predicate.isTagged(error, "HttpApiSchemaError") || Predicate.isTagged(error, "SchemaError"))
    return "Invalid";
  return "Unavailable";
};

// Built per call: `window` only exists in the browser, and the module is also imported by tests.
const makeClient = () => HttpApiClient.make(SurveyBeatApi, { baseUrl: window.location.origin });
export type Client = Effect.Success<ReturnType<typeof makeClient>>;

/** Runs one API call against this origin; the error channel says why it failed. */
export const request = <A, E>(call: (api: Client) => Effect.Effect<A, E>): Effect.Effect<A, Failure> =>
  Effect.suspend(makeClient).pipe(
    Effect.flatMap(call),
    Effect.mapError(failureOf),
    Effect.provide(FetchHttpClient.layer),
  );

import { PulseId, TeamId } from "@surveybeat/domain";
import { Schema, pipe } from "effect";
import { Route } from "foldkit";
import { defineRouteUnion, literal, schemaSegment, slash } from "foldkit/route";

/** The signed-in pages. Any other path inside the app shows the Teams list. */
export const AppRoute = defineRouteUnion({
  Teams: {},
  Team: { teamId: TeamId },
  Pulses: { teamId: TeamId },
  Pulse: { teamId: TeamId, pulseId: PulseId },
  Settings: {},
  NotFound: { path: Schema.String },
});
export type AppRoute = typeof AppRoute.Type;

export const teamsRouter = pipe(Route.root, Route.mapTo(AppRoute.Teams));
export const settingsRouter = pipe(literal("settings"), Route.mapTo(AppRoute.Settings));
export const teamRouter = pipe(
  literal("teams"),
  slash(schemaSegment("teamId", TeamId)),
  Route.mapTo(AppRoute.Team),
);
export const pulsesRouter = pipe(
  literal("teams"),
  slash(schemaSegment("teamId", TeamId)),
  slash(literal("pulses")),
  Route.mapTo(AppRoute.Pulses),
);
export const pulseRouter = pipe(
  literal("teams"),
  slash(schemaSegment("teamId", TeamId)),
  slash(literal("pulses")),
  slash(schemaSegment("pulseId", PulseId)),
  Route.mapTo(AppRoute.Pulse),
);

export const urlToAppRoute = Route.parseUrlWithFallback(
  Route.oneOf(pulseRouter, pulsesRouter, teamRouter, settingsRouter, teamsRouter),
  AppRoute.NotFound,
);

