import { Button, Input, Select } from "@foldkit/ui";
import { Option } from "effect";
import type { Html, HtmlBuilder } from "foldkit/html";
import { message } from "../messages/index.ts";
import type { Failure } from "./api.ts";
import { Change } from "./change.ts";

export const buttonClass = "rounded bg-black px-4 py-2 text-white aria-disabled:opacity-50";
export const linkButtonClass = "text-sm underline aria-disabled:opacity-50";
export const inputClass = "mt-1 w-full rounded border px-3 py-2";
export const labelClass = "block text-sm font-medium";
export const mutedClass = "text-sm text-gray-600";

const failureMessage = (failure: Failure): string => {
  switch (failure) {
    case "Unauthenticated":
      return message("error.Unauthenticated");
    case "Forbidden":
      return message("error.Forbidden");
    case "NotFound":
      return message("error.NotFound");
    case "LastLead":
      return message("error.LastLead");
    case "LastAdmin":
      return message("error.LastAdmin");
    case "TeamNameTaken":
      return message("error.TeamNameTaken");
    case "QuestionAlreadyInPulse":
      return message("error.QuestionAlreadyInPulse");
    case "QuestionHasAnswers":
      return message("error.QuestionHasAnswers");
    case "PulseNeedsAQuestion":
      return message("error.PulseNeedsAQuestion");
    case "PulseFull":
      return message("error.PulseFull");
    case "OrderMismatch":
      return message("error.OrderMismatch");
    case "Invalid":
      return message("error.Invalid");
    case "Unavailable":
      return message("error.Unavailable");
  }
};

/** Why a call failed, announced to screen readers. */
export const problemView = <M>(failure: Failure, h: HtmlBuilder<M>): Html =>
  h.p([h.Role("alert"), h.Class("mt-2 text-red-700")], [failureMessage(failure)]);

/** The failure of a change, if it failed. */
export const changeProblemView = <M>(change: Change, h: HtmlBuilder<M>): Html =>
  Change.match(change, {
    Idle: () => h.empty,
    Busy: () => h.empty,
    Done: () => h.empty,
    Failed: ({ failure }) => problemView(failure, h),
  });

/** A confirmation such as "Saved.", shown once a change is done. */
export const doneView = <M>(change: Change, text: string, h: HtmlBuilder<M>): Html =>
  change._tag === "Done" ? h.p([h.Role("status")], [text]) : h.empty;

export const maybeView = <A>(maybe: Option.Option<A>, f: (value: A) => Html): Html =>
  Option.match(maybe, { onNone: () => null, onSome: f });

export const buttonView = <M>(
  config: {
    readonly text: string;
    readonly className?: string;
    readonly onClick?: M;
    readonly isSubmit?: boolean;
    readonly isDisabled?: boolean;
  },
  h: HtmlBuilder<M>,
): Html =>
  Button.view(
    {
      type: config.isSubmit === true ? "submit" : "button",
      isDisabled: config.isDisabled ?? false,
      ...(config.onClick === undefined ? {} : { onClick: config.onClick }),
      toView: (attributes) =>
        h.button([...attributes.button, h.Class(config.className ?? buttonClass)], [config.text]),
    },
    h,
  );

export const textFieldView = <M>(
  config: {
    readonly id: string;
    readonly label: string;
    readonly value: string;
    readonly onInput: (value: string) => M;
    readonly type?: "text" | "email" | "number" | "time";
  },
  h: HtmlBuilder<M>,
): Html =>
  Input.view(
    {
      id: config.id,
      type: config.type ?? "text",
      value: config.value,
      onInput: config.onInput,
      toView: (attributes) =>
        h.div(
          [],
          [
            h.label([...attributes.label, h.Class(labelClass)], [config.label]),
            h.input([...attributes.input, h.Required(true), h.Class(inputClass)]),
          ],
        ),
    },
    h,
  );

/** A native select over a fixed list of values, each with the text it shows. */
export const selectFieldView = <M>(
  config: {
    readonly id: string;
    readonly label: string;
    readonly value: string;
    readonly options: ReadonlyArray<readonly [string, string]>;
    readonly onChange: (value: string) => M;
  },
  h: HtmlBuilder<M>,
): Html =>
  Select.view(
    {
      id: config.id,
      value: config.value,
      onChange: config.onChange,
      toView: (attributes) =>
        h.div(
          [],
          [
            h.label([...attributes.label, h.Class(labelClass)], [config.label]),
            h.select(
              [...attributes.select, h.Class(inputClass)],
              config.options.map(([value, text]) =>
                h.option([h.Value(value), h.Selected(value === config.value)], [text]),
              ),
            ),
          ],
        ),
    },
    h,
  );

/** A plain form POST, so the browser follows the redirect to WorkOS's logout. */
export const signOutView = <M>(h: HtmlBuilder<M>): Html =>
  h.form(
    [h.Method("post"), h.Action("/auth/logout"), h.Class("mt-6")],
    [buttonView({ text: message("signOut.action"), isSubmit: true, className: "text-sm text-gray-600 underline" }, h)],
  );

import { PulseId, TeamId } from "@surveybeat/domain";
import { defineMessageUnion } from "foldkit/message";
import { defineTaggedUnion } from "foldkit/schema";
import { Failure } from "./api.ts";

/**
 * One change a screen sends, such as a form submit or a remove button. One runs at a time per
 * section; `Done` is kept so a section can confirm it ("Saved.").
 */
export const Change = defineTaggedUnion({
  Idle: {},
  Busy: {},
  Failed: { failure: Failure },
  Done: {},
});
export type Change = typeof Change.Type;

/** What a signed-in page tells the app. The app decides where that leads. */
export const PageOutMessage = defineMessageUnion({
  /** A call came back Unauthenticated: the session ended. */
  EndedSession: {},
  CreatedTeam: { teamId: TeamId },
  CreatedPulse: { teamId: TeamId, pulseId: PulseId },
});
export type PageOutMessage = typeof PageOutMessage.Type;

/**
 * A failed call as the page reports it: an ended session goes up to the app, anything else is
 * kept by `onFailure` so the page can show it.
 */
export const failedWith = <Model>(
  model: Model,
  failure: Failure,
  onFailure: (failure: Failure) => Model,
): { readonly model: Model; readonly outMessage?: PageOutMessage } =>
  failure === "Unauthenticated"
    ? { model, outMessage: PageOutMessage.EndedSession() }
    : { model: onFailure(failure) };

import { EmailAddress, TeamId, TeamName, TeamSummary, TimeZone } from "@surveybeat/domain";
import { Effect, Option, Schema } from "effect";
import { AsyncData, Command, Submodel, type Update } from "foldkit";
import type { Html, HtmlBuilder } from "foldkit/html";
import { defineMessageUnion } from "foldkit/message";
import { taggedStruct } from "foldkit/schema";
import { modifyFields } from "foldkit/struct";
import { message } from "../../messages/index.ts";
import { Failure, request } from "../api.ts";
import { Change, failedWith, PageOutMessage } from "../change.ts";
import { teamRouter } from "../route.ts";
import {
  buttonView,
  changeProblemView,
  mutedClass,
  problemView,
  textFieldView,
} from "../ui.ts";
import { roleName } from "./roles.ts";

// MODEL

const Teams = AsyncData.Schema(Schema.Array(TeamSummary), Failure);

/** The Teams list: every Team for an admin, otherwise the Teams the Person is in. */
export const Model = taggedStruct("TeamsPage", {
  organizationAdmin: Schema.Boolean,
  teams: Teams.schema,
  name: Schema.String,
  timeZone: Schema.String,
  leadEmail: Schema.String,
  creation: Change,
});
export type Model = typeof Model.Type;

// MESSAGE

export const Message = defineMessageUnion({
  SucceededLoadTeams: { teams: Schema.Array(TeamSummary) },
  FailedLoadTeams: { failure: Failure },
  UpdatedName: { value: Schema.String },
  UpdatedTimeZone: { value: Schema.String },
  UpdatedLeadEmail: { value: Schema.String },
  SubmittedCreateTeam: {},
  SucceededCreateTeam: { teamId: TeamId },
  FailedCreateTeam: { failure: Failure },
});
export type Message = typeof Message.Type;

// COMMAND

export const LoadTeams = Command.define("LoadTeams", {
  messages: [Message.SucceededLoadTeams, Message.FailedLoadTeams],
  execute: request((api) => api.directory.listTeams()).pipe(
    Effect.match({
      onSuccess: (teams) => Message.SucceededLoadTeams({ teams }),
      onFailure: (failure) => Message.FailedLoadTeams({ failure }),
    }),
  ),
});

export const CreateTeam = Command.define("CreateTeam", {
  args: { name: TeamName, timeZone: TimeZone, leadEmail: EmailAddress },
  messages: [Message.SucceededCreateTeam, Message.FailedCreateTeam],
  execute: (payload) =>
    request((api) => api.directory.createTeam({ payload })).pipe(
      Effect.match({
        onSuccess: (created) => Message.SucceededCreateTeam({ teamId: created.team.id }),
        onFailure: (failure) => Message.FailedCreateTeam({ failure }),
      }),
    ),
});

// INIT

export const init = (organizationAdmin: boolean, timeZone: string) => ({
  model: Model({
    organizationAdmin,
    teams: Teams.Loading(),
    name: "",
    timeZone,
    leadEmail: "",
    creation: Change.Idle(),
  }),
  commands: [LoadTeams()],
});

// UPDATE

const decodeName = Schema.decodeUnknownOption(TeamName);
const decodeZone = Schema.decodeUnknownOption(TimeZone);
const decodeEmail = Schema.decodeUnknownOption(EmailAddress);

export const update = (model: Model, msg: Message) =>
  Message.match<Update.ReturnWithOutMessage<Model, Message, PageOutMessage>>(msg, {
    SucceededLoadTeams: ({ teams }) => ({
      model: modifyFields(model, { teams: () => Teams.Success({ data: teams }) }),
    }),
    FailedLoadTeams: ({ failure }) =>
      failedWith(model, failure, (failure) =>
        modifyFields(model, { teams: () => Teams.Failure({ error: failure }) }),
      ),
    UpdatedName: ({ value }) => ({ model: modifyFields(model, { name: () => value }) }),
    UpdatedTimeZone: ({ value }) => ({ model: modifyFields(model, { timeZone: () => value }) }),
    UpdatedLeadEmail: ({ value }) => ({ model: modifyFields(model, { leadEmail: () => value }) }),
    SubmittedCreateTeam: () => {
      if (model.creation._tag === "Busy") return { model };
      const name = decodeName(model.name.trim());
      const timeZone = decodeZone(model.timeZone.trim());
      const leadEmail = decodeEmail(model.leadEmail.trim());
      if (Option.isNone(name) || Option.isNone(timeZone) || Option.isNone(leadEmail)) {
        return { model: modifyFields(model, { creation: () => Change.Failed({ failure: "Invalid" }) }) };
      }
      return {
        model: modifyFields(model, { creation: () => Change.Busy() }),
        commands: [CreateTeam({ name: name.value, timeZone: timeZone.value, leadEmail: leadEmail.value })],
      };
    },
    SucceededCreateTeam: ({ teamId }) => ({
      model: modifyFields(model, { creation: () => Change.Done() }),
      outMessage: PageOutMessage.CreatedTeam({ teamId }),
    }),
    FailedCreateTeam: ({ failure }) =>
      failedWith(model, failure, (failure) =>
        modifyFields(model, { creation: () => Change.Failed({ failure }) }),
      ),
  });

// VIEW

const teamListView = (teams: ReadonlyArray<TeamSummary>, h: HtmlBuilder<Message>): Html =>
  teams.length === 0
    ? h.p([h.Class("mt-2 text-gray-600")], [message("teams.empty")])
    : h.ul(
        [h.Class("mt-3 flex flex-col gap-2")],
        teams.map((team) =>
          h.li(
            [h.Key(team.id)],
            [
              h.a(
                [h.Href(teamRouter({ teamId: team.id })), h.Class("flex justify-between rounded border px-3 py-2")],
                [
                  h.span([], [team.name]),
                  team.yourRole === null
                    ? h.empty
                    : h.span([h.Class(mutedClass)], [message("teams.yourRole", { role: roleName(team.yourRole) })]),
                ],
              ),
            ],
          ),
        ),
      );

const createTeamView = (model: Model, h: HtmlBuilder<Message>): Html =>
  h.form(
    [h.Class("mt-6 flex flex-col gap-3"), h.OnSubmit(Message.SubmittedCreateTeam())],
    [
      h.h2([h.Class("text-xl font-semibold")], [message("teams.create.title")]),
      textFieldView(
        {
          id: "create-team-name",
          label: message("teams.create.name"),
          value: model.name,
          onInput: (value) => Message.UpdatedName({ value }),
        },
        h,
      ),
      textFieldView(
        {
          id: "create-team-time-zone",
          label: message("teams.create.timeZone"),
          value: model.timeZone,
          onInput: (value) => Message.UpdatedTimeZone({ value }),
        },
        h,
      ),
      textFieldView(
        {
          id: "create-team-lead-email",
          label: message("teams.create.leadEmail"),
          value: model.leadEmail,
          onInput: (value) => Message.UpdatedLeadEmail({ value }),
          type: "email",
        },
        h,
      ),
      changeProblemView(model.creation, h),
      buttonView(
        { text: message("teams.create.action"), isSubmit: true, isDisabled: model.creation._tag === "Busy" },
        h,
      ),
    ],
  );

export const view = Submodel.defineView<Model, Message>((model, h) =>
  h.section(
    [h.Class("mt-6")],
    [
      h.h2([h.Class("text-xl font-semibold")], [message("teams.title")]),
      AsyncData.match(model.teams, {
        onIdle: () => h.empty,
        onLoading: () => h.empty,
        onRefreshing: (teams) => teamListView(teams, h),
        onFailure: (failure) => problemView(failure, h),
        onStale: ({ data }) => teamListView(data, h),
        onSuccess: (teams) => teamListView(teams, h),
      }),
      model.organizationAdmin ? createTeamView(model, h) : h.empty,
    ],
  ),
);

