import {
  AssignableRole,
  EmailAddress,
  PersonId,
  type RosterEntry,
  TeamDetail,
  TeamId,
  TeamName,
  TimeZone,
} from "@surveybeat/domain";
import { Effect, Option, Schema } from "effect";
import { AsyncData, Command, Submodel, type Update } from "foldkit";
import type { Html, HtmlBuilder } from "foldkit/html";
import { defineMessageUnion } from "foldkit/message";
import { taggedStruct } from "foldkit/schema";
import { modifyFields } from "foldkit/struct";
import { formatDate, message } from "../../messages/index.ts";
import { Failure, request } from "../api.ts";
import { Change, failedWith, type PageOutMessage } from "../change.ts";
import { pulsesRouter, teamsRouter } from "../route.ts";
import {
  buttonView,
  changeProblemView,
  doneView,
  linkButtonClass,
  mutedClass,
  problemView,
  textFieldView,
} from "../ui.ts";
import { roleName } from "./roles.ts";

// MODEL

const Detail = AsyncData.Schema(TeamDetail, Failure);

/** A form that adds a Person to the Team by email: as a member, or as a Lead. */
const EmailForm = Schema.Struct({ email: Schema.String, change: Change });

/** One Team: members and Leads, add by email, remove. Never any Results (ADR 0003). */
export const Model = taggedStruct("TeamPage", {
  teamId: TeamId,
  detail: Detail.schema,
  name: Schema.String,
  timeZone: Schema.String,
  rename: Change,
  roster: Change,
  member: EmailForm,
  lead: EmailForm,
});
export type Model = typeof Model.Type;

// MESSAGE

export const Message = defineMessageUnion({
  SucceededLoadTeam: { detail: TeamDetail },
  FailedLoadTeam: { failure: Failure },
  UpdatedName: { value: Schema.String },
  UpdatedTimeZone: { value: Schema.String },
  SubmittedRename: {},
  SucceededRenameTeam: {},
  FailedRenameTeam: { failure: Failure },
  ClickedRemove: { personId: PersonId, role: AssignableRole },
  SucceededRemoveFromTeam: {},
  FailedRemoveFromTeam: { failure: Failure },
  UpdatedEmail: { role: AssignableRole, value: Schema.String },
  SubmittedEmail: { role: AssignableRole },
  SucceededAddToTeam: { role: AssignableRole },
  FailedAddToTeam: { role: AssignableRole, failure: Failure },
});
export type Message = typeof Message.Type;

// COMMAND

export const LoadTeam = Command.define("LoadTeam", {
  args: { teamId: TeamId },
  messages: [Message.SucceededLoadTeam, Message.FailedLoadTeam],
  execute: ({ teamId }) =>
    request((api) => api.directory.getTeam({ params: { teamId } })).pipe(
      Effect.match({
        onSuccess: (detail) => Message.SucceededLoadTeam({ detail }),
        onFailure: (failure) => Message.FailedLoadTeam({ failure }),
      }),
    ),
});

export const RenameTeam = Command.define("RenameTeam", {
  args: { teamId: TeamId, name: TeamName, timeZone: TimeZone },
  messages: [Message.SucceededRenameTeam, Message.FailedRenameTeam],
  execute: ({ teamId, name, timeZone }) =>
    request((api) => api.directory.updateTeam({ params: { teamId }, payload: { name, timeZone } })).pipe(
      Effect.match({
        onSuccess: () => Message.SucceededRenameTeam(),
        onFailure: (failure) => Message.FailedRenameTeam({ failure }),
      }),
    ),
});

export const RemoveFromTeam = Command.define("RemoveFromTeam", {
  args: { teamId: TeamId, personId: PersonId, role: AssignableRole },
  messages: [Message.SucceededRemoveFromTeam, Message.FailedRemoveFromTeam],
  execute: ({ teamId, personId, role }) =>
    request((api) =>
      role === "lead"
        ? api.directory.removeLead({ params: { teamId, personId } })
        : api.directory.removeMember({ params: { teamId, personId } }),
    ).pipe(
      Effect.match({
        onSuccess: () => Message.SucceededRemoveFromTeam(),
        onFailure: (failure) => Message.FailedRemoveFromTeam({ failure }),
      }),
    ),
});

export const AddToTeam = Command.define("AddToTeam", {
  args: { teamId: TeamId, role: AssignableRole, email: EmailAddress },
  messages: [Message.SucceededAddToTeam, Message.FailedAddToTeam],
  execute: ({ teamId, role, email }) =>
    request((api) =>
      role === "lead"
        ? api.directory.assignLead({ params: { teamId }, payload: { email } })
        : api.directory.addMember({ params: { teamId }, payload: { email } }),
    ).pipe(
      Effect.match({
        onSuccess: () => Message.SucceededAddToTeam({ role }),
        onFailure: (failure) => Message.FailedAddToTeam({ role, failure }),
      }),
    ),
});

// INIT

export const init = (teamId: TeamId) => ({
  model: Model({
    teamId,
    detail: Detail.Loading(),
    name: "",
    timeZone: "",
    rename: Change.Idle(),
    roster: Change.Idle(),
    member: { email: "", change: Change.Idle() },
    lead: { email: "", change: Change.Idle() },
  }),
  commands: [LoadTeam({ teamId })],
});

// UPDATE

type UpdateReturn = Update.ReturnWithOutMessage<Model, Message, PageOutMessage>;

const decodeName = Schema.decodeUnknownOption(TeamName);
const decodeZone = Schema.decodeUnknownOption(TimeZone);
const decodeEmail = Schema.decodeUnknownOption(EmailAddress);

/** Loads the Team again after every change: a change can end the caller's own access. */
const reload = (model: Model): UpdateReturn => ({
  model: modifyFields(model, {
    detail: (detail) =>
      detail._tag === "Success" ? Detail.Refreshing({ data: detail.data }) : Detail.Loading(),
  }),
  commands: [LoadTeam({ teamId: model.teamId })],
});

const formOf = (model: Model, role: AssignableRole) => (role === "lead" ? model.lead : model.member);

const withForm = (
  model: Model,
  role: AssignableRole,
  change: (form: typeof EmailForm.Type) => typeof EmailForm.Type,
): Model =>
  role === "lead"
    ? modifyFields(model, { lead: change })
    : modifyFields(model, { member: change });

const isBusy = (change: Change) => change._tag === "Busy";

export const update = (model: Model, msg: Message) =>
  Message.match<UpdateReturn>(msg, {
    SucceededLoadTeam: ({ detail }) => ({
      // The name and time zone fields start from the first load and keep what was typed after.
      model:
        model.detail._tag === "Loading"
          ? modifyFields(model, {
              detail: () => Detail.Success({ data: detail }),
              name: () => detail.team.name,
              timeZone: () => detail.team.timeZone,
            })
          : modifyFields(model, { detail: () => Detail.Success({ data: detail }) }),
    }),
    FailedLoadTeam: ({ failure }) =>
      failedWith(model, failure, (failure) =>
        modifyFields(model, { detail: () => Detail.Failure({ error: failure }) }),
      ),

    UpdatedName: ({ value }) => ({ model: modifyFields(model, { name: () => value }) }),
    UpdatedTimeZone: ({ value }) => ({ model: modifyFields(model, { timeZone: () => value }) }),
    SubmittedRename: () => {
      if (isBusy(model.rename)) return { model };
      const name = decodeName(model.name.trim());
      const timeZone = decodeZone(model.timeZone.trim());
      if (Option.isNone(name) || Option.isNone(timeZone)) {
        return { model: modifyFields(model, { rename: () => Change.Failed({ failure: "Invalid" }) }) };
      }
      return {
        model: modifyFields(model, { rename: () => Change.Busy() }),
        commands: [RenameTeam({ teamId: model.teamId, name: name.value, timeZone: timeZone.value })],
      };
    },
    SucceededRenameTeam: () => reload(modifyFields(model, { rename: () => Change.Done() })),
    FailedRenameTeam: ({ failure }) =>
      failedWith(model, failure, (failure) => modifyFields(model, { rename: () => Change.Failed({ failure }) })),

    ClickedRemove: ({ personId, role }) =>
      isBusy(model.roster)
        ? { model }
        : {
            model: modifyFields(model, { roster: () => Change.Busy() }),
            commands: [RemoveFromTeam({ teamId: model.teamId, personId, role })],
          },
    SucceededRemoveFromTeam: () => reload(modifyFields(model, { roster: () => Change.Done() })),
    FailedRemoveFromTeam: ({ failure }) =>
      failedWith(model, failure, (failure) => modifyFields(model, { roster: () => Change.Failed({ failure }) })),

    UpdatedEmail: ({ role, value }) => ({
      model: withForm(model, role, (form) => ({ ...form, email: value })),
    }),
    SubmittedEmail: ({ role }) => {
      const form = formOf(model, role);
      if (isBusy(form.change)) return { model };
      const email = decodeEmail(form.email.trim());
      if (Option.isNone(email)) {
        return {
          model: withForm(model, role, (form) => ({ ...form, change: Change.Failed({ failure: "Invalid" }) })),
        };
      }
      return {
        model: withForm(model, role, (form) => ({ ...form, change: Change.Busy() })),
        commands: [AddToTeam({ teamId: model.teamId, role, email: email.value })],
      };
    },
    SucceededAddToTeam: ({ role }) =>
      reload(withForm(model, role, () => ({ email: "", change: Change.Done() }))),
    FailedAddToTeam: ({ role, failure }) =>
      failedWith(model, failure, (failure) =>
        withForm(model, role, (form) => ({ ...form, change: Change.Failed({ failure }) })),
      ),
  });

// VIEW

const renameView = (model: Model, h: HtmlBuilder<Message>): Html =>
  h.form(
    [h.Class("mt-4 flex flex-col gap-3"), h.OnSubmit(Message.SubmittedRename())],
    [
      h.h3([h.Class("text-lg font-medium")], [message("team.rename.title")]),
      textFieldView(
        {
          id: "team-name",
          label: message("teams.create.name"),
          value: model.name,
          onInput: (value) => Message.UpdatedName({ value }),
        },
        h,
      ),
      textFieldView(
        {
          id: "team-time-zone",
          label: message("teams.create.timeZone"),
          value: model.timeZone,
          onInput: (value) => Message.UpdatedTimeZone({ value }),
        },
        h,
      ),
      changeProblemView(model.rename, h),
      buttonView(
        { text: message("team.rename.action"), isSubmit: true, isDisabled: isBusy(model.rename) },
        h,
      ),
    ],
  );

const rosterEntryView = (
  model: Model,
  detail: TeamDetail,
  entry: RosterEntry,
  h: HtmlBuilder<Message>,
): Html => {
  const isLead = entry.role === "lead";
  const mayRemove = isLead ? detail.may.manageLeads : detail.may.manageMembers;
  return h.li(
    [h.Key(entry.personId), h.Class("flex items-center justify-between rounded border px-3 py-2")],
    [
      h.span(
        [],
        [
          `${entry.email} `,
          h.span([h.Class(mutedClass)], [roleName(entry.role)]),
          " ",
          h.span([h.Class(mutedClass)], [message("team.since", { date: formatDate(new Date(entry.since)) })]),
        ],
      ),
      mayRemove
        ? buttonView(
            {
              text: message(isLead ? "team.removeLead" : "team.removeMember"),
              className: "text-sm underline",
              isDisabled: isBusy(model.roster),
              onClick: Message.ClickedRemove({ personId: entry.personId, role: isLead ? "lead" : "member" }),
            },
            h,
          )
        : h.empty,
    ],
  );
};

const emailFormView = (
  model: Model,
  role: AssignableRole,
  h: HtmlBuilder<Message>,
): Html => {
  const form = formOf(model, role);
  return h.form(
    [h.Class("mt-4 flex flex-col gap-3"), h.OnSubmit(Message.SubmittedEmail({ role }))],
    [
      textFieldView(
        {
          id: `team-${role}-email`,
          label: message(role === "lead" ? "team.assignLead.label" : "team.addMember.label"),
          value: form.email,
          onInput: (value) => Message.UpdatedEmail({ role, value }),
          type: "email",
        },
        h,
      ),
      changeProblemView(form.change, h),
      doneView(form.change, message("team.added"), h),
      buttonView(
        {
          text: message(role === "lead" ? "team.assignLead.action" : "team.addMember.action"),
          isSubmit: true,
          isDisabled: isBusy(form.change),
        },
        h,
      ),
    ],
  );
};

const detailView = (model: Model, detail: TeamDetail, h: HtmlBuilder<Message>): Html =>
  h.div(
    [],
    [
      h.h2([h.Class("mt-2 text-xl font-semibold")], [detail.team.name]),
      h.p([h.Class(mutedClass)], [message("team.timeZone", { timeZone: detail.team.timeZone })]),
      detail.team.yourRole === null
        ? h.p([h.Class(`mt-2 ${mutedClass}`)], [message("team.noResultsAccess")])
        : h.empty,
      detail.may.managePulses
        ? h.a(
            [h.Href(pulsesRouter({ teamId: model.teamId })), h.Class("mt-4 inline-block underline")],
            [message("team.pulses")],
          )
        : h.empty,
      detail.may.update ? renameView(model, h) : h.empty,
      h.h3([h.Class("mt-6 text-lg font-medium")], [message("team.roster")]),
      h.ul(
        [h.Class("mt-2 flex flex-col gap-2")],
        detail.roster.map((entry) => rosterEntryView(model, detail, entry, h)),
      ),
      changeProblemView(model.roster, h),
      detail.may.manageMembers ? emailFormView(model, "member", h) : h.empty,
      detail.may.manageLeads ? emailFormView(model, "lead", h) : h.empty,
    ],
  );

export const view = Submodel.defineView<Model, Message>((model, h) =>
  h.section(
    [h.Class("mt-6")],
    [
      h.a([h.Href(teamsRouter()), h.Class("text-sm underline")], [message("team.back")]),
      AsyncData.match(model.detail, {
        onIdle: () => h.empty,
        onLoading: () => h.empty,
        onRefreshing: (detail) => detailView(model, detail, h),
        onFailure: (failure) => problemView(failure, h),
        onStale: ({ data }) => detailView(model, data, h),
        onSuccess: (detail) => detailView(model, detail, h),
      }),
    ],
  ),
);

export { linkButtonClass };

