import { MinimumGroupSize, OrganizationSettings, PersonId, type PersonSummary } from "@surveybeat/domain";
import { Effect, Option, Schema } from "effect";
import { AsyncData, Command, Submodel, type Update } from "foldkit";
import type { Html, HtmlBuilder } from "foldkit/html";
import { defineMessageUnion } from "foldkit/message";
import { taggedStruct } from "foldkit/schema";
import { modifyFields } from "foldkit/struct";
import { message } from "../../messages/index.ts";
import { Failure, request } from "../api.ts";
import { Change, failedWith, type PageOutMessage } from "../change.ts";
import { buttonView, changeProblemView, doneView, mutedClass, problemView, textFieldView } from "../ui.ts";

// MODEL

const Settings = AsyncData.Schema(OrganizationSettings, Failure);

/** Organization settings: N, and the People (admin role, removal). Organization admins only. */
export const Model = taggedStruct("SettingsPage", {
  settings: Settings.schema,
  minimumGroupSize: Schema.String,
  save: Change,
  people: Change,
});
export type Model = typeof Model.Type;

// MESSAGE

/** What an admin does to one Person on this screen. */
const PersonChange = Schema.Literals(["grantAdmin", "revokeAdmin", "remove"]);

export const Message = defineMessageUnion({
  SucceededLoadSettings: { settings: OrganizationSettings },
  FailedLoadSettings: { failure: Failure },
  UpdatedMinimumGroupSize: { value: Schema.String },
  SubmittedMinimumGroupSize: {},
  SucceededSaveMinimumGroupSize: {},
  FailedSaveMinimumGroupSize: { failure: Failure },
  ClickedPersonChange: { personId: PersonId, change: PersonChange },
  SucceededChangePerson: {},
  FailedChangePerson: { failure: Failure },
});
export type Message = typeof Message.Type;

// COMMAND

export const LoadSettings = Command.define("LoadSettings", {
  messages: [Message.SucceededLoadSettings, Message.FailedLoadSettings],
  execute: request((api) => api.directory.getSettings()).pipe(
    Effect.match({
      onSuccess: (settings) => Message.SucceededLoadSettings({ settings }),
      onFailure: (failure) => Message.FailedLoadSettings({ failure }),
    }),
  ),
});

export const SaveMinimumGroupSize = Command.define("SaveMinimumGroupSize", {
  args: { minimumGroupSize: MinimumGroupSize },
  messages: [Message.SucceededSaveMinimumGroupSize, Message.FailedSaveMinimumGroupSize],
  execute: (payload) =>
    request((api) => api.directory.updateSettings({ payload })).pipe(
      Effect.match({
        onSuccess: () => Message.SucceededSaveMinimumGroupSize(),
        onFailure: (failure) => Message.FailedSaveMinimumGroupSize({ failure }),
      }),
    ),
});

export const ChangePerson = Command.define("ChangePerson", {
  args: { personId: PersonId, change: PersonChange },
  messages: [Message.SucceededChangePerson, Message.FailedChangePerson],
  execute: ({ personId, change }) =>
    request((api) => {
      const params = { params: { personId } };
      switch (change) {
        case "grantAdmin":
          return api.directory.grantAdmin(params);
        case "revokeAdmin":
          return api.directory.revokeAdmin(params);
        case "remove":
          return api.directory.removePerson(params);
      }
    }).pipe(
      Effect.match({
        onSuccess: () => Message.SucceededChangePerson(),
        onFailure: (failure) => Message.FailedChangePerson({ failure }),
      }),
    ),
});

// INIT

export const init = () => ({
  model: Model({
    settings: Settings.Loading(),
    minimumGroupSize: "",
    save: Change.Idle(),
    people: Change.Idle(),
  }),
  commands: [LoadSettings()],
});

// UPDATE

type UpdateReturn = Update.ReturnWithOutMessage<Model, Message, PageOutMessage>;

const decodeSize = Schema.decodeUnknownOption(MinimumGroupSize);
const isBusy = (change: Change) => change._tag === "Busy";

/** Loads the settings again after every change: a change can end the caller's own admin role. */
const reload = (model: Model): UpdateReturn => ({
  model: modifyFields(model, {
    settings: (settings) =>
      settings._tag === "Success" ? Settings.Refreshing({ data: settings.data }) : Settings.Loading(),
  }),
  commands: [LoadSettings()],
});

export const update = (model: Model, msg: Message) =>
  Message.match<UpdateReturn>(msg, {
    SucceededLoadSettings: ({ settings }) => ({
      // The N field starts from the first load and keeps what was typed after.
      model:
        model.settings._tag === "Loading"
          ? modifyFields(model, {
              settings: () => Settings.Success({ data: settings }),
              minimumGroupSize: () => String(settings.minimumGroupSize),
            })
          : modifyFields(model, { settings: () => Settings.Success({ data: settings }) }),
    }),
    FailedLoadSettings: ({ failure }) =>
      failedWith(model, failure, (failure) =>
        modifyFields(model, { settings: () => Settings.Failure({ error: failure }) }),
      ),

    UpdatedMinimumGroupSize: ({ value }) => ({
      model: modifyFields(model, { minimumGroupSize: () => value }),
    }),
    SubmittedMinimumGroupSize: () => {
      if (isBusy(model.save)) return { model };
      const minimumGroupSize = decodeSize(Number(model.minimumGroupSize));
      if (Option.isNone(minimumGroupSize)) {
        return { model: modifyFields(model, { save: () => Change.Failed({ failure: "Invalid" }) }) };
      }
      return {
        model: modifyFields(model, { save: () => Change.Busy() }),
        commands: [SaveMinimumGroupSize({ minimumGroupSize: minimumGroupSize.value })],
      };
    },
    SucceededSaveMinimumGroupSize: () => reload(modifyFields(model, { save: () => Change.Done() })),
    FailedSaveMinimumGroupSize: ({ failure }) =>
      failedWith(model, failure, (failure) => modifyFields(model, { save: () => Change.Failed({ failure }) })),

    ClickedPersonChange: ({ personId, change }) =>
      isBusy(model.people)
        ? { model }
        : {
            model: modifyFields(model, { people: () => Change.Busy() }),
            commands: [ChangePerson({ personId, change })],
          },
    SucceededChangePerson: () => reload(modifyFields(model, { people: () => Change.Done() })),
    FailedChangePerson: ({ failure }) =>
      failedWith(model, failure, (failure) => modifyFields(model, { people: () => Change.Failed({ failure }) })),
  });

// VIEW

const minimumGroupSizeView = (model: Model, h: HtmlBuilder<Message>): Html =>
  h.form(
    [h.Class("mt-4 flex flex-col gap-3"), h.OnSubmit(Message.SubmittedMinimumGroupSize())],
    [
      textFieldView(
        {
          id: "settings-minimum-group-size",
          label: message("settings.minimumGroupSize"),
          value: model.minimumGroupSize,
          onInput: (value) => Message.UpdatedMinimumGroupSize({ value }),
          type: "number",
        },
        h,
      ),
      h.p([h.Class(mutedClass)], [message("settings.minimumGroupSize.help")]),
      changeProblemView(model.save, h),
      doneView(model.save, message("settings.saved"), h),
      buttonView({ text: message("settings.save"), isSubmit: true, isDisabled: isBusy(model.save) }, h),
    ],
  );

const personView = (model: Model, person: PersonSummary, h: HtmlBuilder<Message>): Html =>
  h.li(
    [h.Key(person.personId), h.Class("rounded border px-3 py-2")],
    [
      h.p(
        [],
        [
          person.email,
          person.organizationAdmin ? h.span([h.Class(`ml-2 ${mutedClass}`)], [message("settings.admin")]) : h.empty,
          person.linked ? h.empty : h.span([h.Class(`ml-2 ${mutedClass}`)], [message("settings.notSignedInYet")]),
        ],
      ),
      h.div(
        [h.Class("mt-1 flex gap-4 text-sm")],
        [
          buttonView(
            {
              text: message(person.organizationAdmin ? "settings.revokeAdmin" : "settings.makeAdmin"),
              className: "underline",
              isDisabled: isBusy(model.people),
              onClick: Message.ClickedPersonChange({
                personId: person.personId,
                change: person.organizationAdmin ? "revokeAdmin" : "grantAdmin",
              }),
            },
            h,
          ),
          buttonView(
            {
              text: message("settings.removePerson"),
              className: "underline",
              isDisabled: isBusy(model.people),
              onClick: Message.ClickedPersonChange({ personId: person.personId, change: "remove" }),
            },
            h,
          ),
        ],
      ),
    ],
  );

const settingsView = (model: Model, settings: OrganizationSettings, h: HtmlBuilder<Message>): Html =>
  h.div(
    [],
    [
      minimumGroupSizeView(model, h),
      h.h3([h.Class("mt-6 text-lg font-medium")], [message("settings.people")]),
      h.ul(
        [h.Class("mt-2 flex flex-col gap-2")],
        settings.people.map((person) => personView(model, person, h)),
      ),
      changeProblemView(model.people, h),
    ],
  );

export const view = Submodel.defineView<Model, Message>((model, h) =>
  h.section(
    [h.Class("mt-6")],
    [
      h.h2([h.Class("text-xl font-semibold")], [message("settings.title")]),
      AsyncData.match(model.settings, {
        onIdle: () => h.empty,
        onLoading: () => h.empty,
        onRefreshing: (settings) => settingsView(model, settings, h),
        onFailure: (failure) => problemView(failure, h),
        onStale: ({ data }) => settingsView(model, data, h),
        onSuccess: (settings) => settingsView(model, settings, h),
      }),
    ],
  ),
);

import { PulseId, PulseList, type PulseSummary, TeamId } from "@surveybeat/domain";
import { Effect, Schema } from "effect";
import { AsyncData, Command, Submodel, type Update } from "foldkit";
import type { Html, HtmlBuilder } from "foldkit/html";
import { defineMessageUnion } from "foldkit/message";
import { taggedStruct } from "foldkit/schema";
import { modifyFields } from "foldkit/struct";
import { message, pluralMessage } from "../../messages/index.ts";
import { Failure, request } from "../api.ts";
import { Change, failedWith, PageOutMessage } from "../change.ts";
import { pulseRouter, teamRouter } from "../route.ts";
import { buttonClass, buttonView, changeProblemView, mutedClass, problemView } from "../ui.ts";

// MODEL

const List = AsyncData.Schema(PulseList, Failure);

/** A Team's Pulses, and a button that creates one from the weekly team health Template. */
export const Model = taggedStruct("PulsesPage", {
  teamId: TeamId,
  list: List.schema,
  creation: Change,
});
export type Model = typeof Model.Type;

// MESSAGE

export const Message = defineMessageUnion({
  SucceededLoadPulses: { list: PulseList },
  FailedLoadPulses: { failure: Failure },
  ClickedCreatePulse: {},
  SucceededCreatePulse: { pulseId: PulseId },
  FailedCreatePulse: { failure: Failure },
});
export type Message = typeof Message.Type;

// COMMAND

export const LoadPulses = Command.define("LoadPulses", {
  args: { teamId: TeamId },
  messages: [Message.SucceededLoadPulses, Message.FailedLoadPulses],
  execute: ({ teamId }) =>
    request((api) => api.pulses.listPulses({ params: { teamId } })).pipe(
      Effect.match({
        onSuccess: (list) => Message.SucceededLoadPulses({ list }),
        onFailure: (failure) => Message.FailedLoadPulses({ failure }),
      }),
    ),
});

export const CreatePulse = Command.define("CreatePulse", {
  args: { teamId: TeamId },
  messages: [Message.SucceededCreatePulse, Message.FailedCreatePulse],
  execute: ({ teamId }) =>
    request((api) => api.pulses.createPulse({ params: { teamId } })).pipe(
      Effect.match({
        onSuccess: (created) => Message.SucceededCreatePulse({ pulseId: created.id }),
        onFailure: (failure) => Message.FailedCreatePulse({ failure }),
      }),
    ),
});

// INIT

export const init = (teamId: TeamId) => ({
  model: Model({ teamId, list: List.Loading(), creation: Change.Idle() }),
  commands: [LoadPulses({ teamId })],
});

// UPDATE

export const update = (model: Model, msg: Message) =>
  Message.match<Update.ReturnWithOutMessage<Model, Message, PageOutMessage>>(msg, {
    SucceededLoadPulses: ({ list }) => ({
      model: modifyFields(model, { list: () => List.Success({ data: list }) }),
    }),
    FailedLoadPulses: ({ failure }) =>
      failedWith(model, failure, (failure) => modifyFields(model, { list: () => List.Failure({ error: failure }) })),
    ClickedCreatePulse: () =>
      model.creation._tag === "Busy"
        ? { model }
        : {
            model: modifyFields(model, { creation: () => Change.Busy() }),
            commands: [CreatePulse({ teamId: model.teamId })],
          },
    SucceededCreatePulse: ({ pulseId }) => ({
      model: modifyFields(model, { creation: () => Change.Done() }),
      outMessage: PageOutMessage.CreatedPulse({ teamId: model.teamId, pulseId }),
    }),
    FailedCreatePulse: ({ failure }) =>
      failedWith(model, failure, (failure) => modifyFields(model, { creation: () => Change.Failed({ failure }) })),
  });

// VIEW

const summaryView = (teamId: TeamId, pulse: PulseSummary, h: HtmlBuilder<Message>): Html =>
  h.li(
    [h.Key(pulse.id)],
    [
      h.a(
        [
          h.Href(pulseRouter({ teamId, pulseId: pulse.id })),
          h.Class("flex justify-between rounded border px-3 py-2"),
        ],
        [
          h.span([], [pulse.name]),
          h.span(
            [h.Class(mutedClass)],
            [
              message("pulses.summary", {
                day: message(`weekday.${pulse.cadence.day}`),
                time: pulse.cadence.time,
                questions: pluralMessage("pulse.questionCount", pulse.questionCount),
                seconds: pulse.estimatedSeconds,
              }),
            ],
          ),
        ],
      ),
    ],
  );

const listView = (model: Model, list: PulseList, h: HtmlBuilder<Message>): Html =>
  h.div(
    [],
    [
      h.h2([h.Class("mt-2 text-xl font-semibold")], [message("pulses.title", { team: list.team.name })]),
      list.pulses.length === 0
        ? h.p([h.Class("mt-2 text-gray-600")], [message("pulses.empty")])
        : h.ul(
            [h.Class("mt-3 flex flex-col gap-2")],
            list.pulses.map((pulse) => summaryView(model.teamId, pulse, h)),
          ),
      h.p([h.Class(`mt-6 ${mutedClass}`)], [message("pulses.create.intro")]),
      changeProblemView(model.creation, h),
      buttonView(
        {
          text: message("pulses.create.action"),
          className: `mt-2 ${buttonClass}`,
          isDisabled: model.creation._tag === "Busy",
          onClick: Message.ClickedCreatePulse(),
        },
        h,
      ),
    ],
  );

export const view = Submodel.defineView<Model, Message>((model, h) =>
  h.section(
    [h.Class("mt-6")],
    [
      h.a([h.Href(teamRouter({ teamId: model.teamId })), h.Class("text-sm underline")], [message("pulses.back")]),
      AsyncData.match(model.list, {
        onIdle: () => h.empty,
        onLoading: () => h.empty,
        onRefreshing: (list) => listView(model, list, h),
        onFailure: (failure) => problemView(failure, h),
        onStale: ({ data }) => listView(model, data, h),
        onSuccess: (list) => listView(model, list, h),
      }),
    ],
  ),
);

import { Checkbox, Textarea } from "@foldkit/ui";
import { Dimension, type PulseQuestion, QuestionContent } from "@surveybeat/domain";
import { Option, Schema } from "effect";
import type { Html, HtmlBuilder } from "foldkit/html";
import { message } from "../../messages/index.ts";
import { Change } from "../change.ts";
import {
  buttonView,
  changeProblemView,
  inputClass,
  labelClass,
  mutedClass,
  selectFieldView,
  textFieldView,
} from "../ui.ts";

// MODEL

const Kind = Schema.Literals(["Rating", "SingleChoice", "LongText"]);
type Kind = typeof Kind.Type;

const DimensionChoice = Schema.Union([Schema.Literal("none"), Dimension]);
type DimensionChoice = typeof DimensionChoice.Type;

/** A Question being written or rewritten, as typed: plain strings until it is submitted. */
export const QuestionForm = Schema.Struct({
  text: Schema.String,
  kind: Kind,
  lowLabel: Schema.String,
  highLabel: Schema.String,
  comment: Schema.Boolean,
  options: Schema.String,
  dimension: DimensionChoice,
  change: Change,
});
export type QuestionForm = typeof QuestionForm.Type;

/** The text fields of the form; the selects and the checkbox have their own Messages. */
export const QuestionField = Schema.Literals(["text", "lowLabel", "highLabel", "options"]);
export type QuestionField = typeof QuestionField.Type;

/** An empty form, or one holding an existing Question. */
export const questionForm = (question?: PulseQuestion): QuestionForm => {
  const type = question?.type;
  return {
    text: question?.text ?? "",
    kind: type?._tag ?? "Rating",
    lowLabel: type?._tag === "Rating" ? type.lowLabel : "",
    highLabel: type?._tag === "Rating" ? type.highLabel : "",
    comment: type?._tag === "Rating" ? type.comment : true,
    options: type?._tag === "SingleChoice" ? type.options.join("\n") : "",
    dimension: question?.dimension ?? "none",
    change: Change.Idle(),
  };
};

// UPDATE

const decodeKind = Schema.decodeUnknownOption(Kind);
const decodeDimension = Schema.decodeUnknownOption(DimensionChoice);
const decodeContent = Schema.decodeUnknownOption(QuestionContent);

export const withField = (form: QuestionForm, field: QuestionField, value: string): QuestionForm => ({
  ...form,
  [field]: value,
});

export const withKind = (form: QuestionForm, value: string): QuestionForm =>
  Option.match(decodeKind(value), { onNone: () => form, onSome: (kind) => ({ ...form, kind }) });

export const withDimension = (form: QuestionForm, value: string): QuestionForm =>
  Option.match(decodeDimension(value), { onNone: () => form, onSome: (dimension) => ({ ...form, dimension }) });

/** What the form says, if it is a valid Question. */
export const contentOf = (form: QuestionForm): Option.Option<QuestionContent> => {
  const type =
    form.kind === "Rating"
      ? { _tag: form.kind, lowLabel: form.lowLabel.trim(), highLabel: form.highLabel.trim(), comment: form.comment }
      : form.kind === "SingleChoice"
        ? {
            _tag: form.kind,
            options: form.options
              .split("\n")
              .map((option) => option.trim())
              .filter((option) => option !== ""),
          }
        : { _tag: form.kind };
  return decodeContent({
    text: form.text.trim(),
    dimension: form.dimension === "none" ? null : form.dimension,
    type,
  });
};

// VIEW

const KINDS: ReadonlyArray<readonly [Kind, string]> = Kind.literals.map(
  (kind) => [kind, message(`questionType.${kind}`)] as const,
);
const DIMENSIONS: ReadonlyArray<readonly [DimensionChoice, string]> = [
  ["none", message("dimension.none")],
  ...Dimension.literals.map((dimension) => [dimension, message(`dimension.${dimension}`)] as const),
];

export interface QuestionFormEvents<M> {
  /** Makes the field ids unique on the page. */
  readonly id: string;
  readonly title: string;
  readonly action: string;
  readonly onField: (field: QuestionField, value: string) => M;
  readonly onKind: (value: string) => M;
  readonly onDimension: (value: string) => M;
  readonly onComment: (isChecked: boolean) => M;
  readonly onSubmit: M;
}

/** Writes a new Question, or rewrites one without Answers. */
export const questionFormView = <M>(form: QuestionForm, events: QuestionFormEvents<M>, h: HtmlBuilder<M>): Html =>
  h.form(
    [h.Class("mt-4 flex flex-col gap-3 rounded border p-3"), h.OnSubmit(events.onSubmit)],
    [
      h.h4([h.Class("font-medium")], [events.title]),
      textFieldView(
        {
          id: `${events.id}-text`,
          label: message("question.text"),
          value: form.text,
          onInput: (value) => events.onField("text", value),
        },
        h,
      ),
      selectFieldView(
        {
          id: `${events.id}-type`,
          label: message("question.type"),
          value: form.kind,
          options: KINDS,
          onChange: events.onKind,
        },
        h,
      ),
      ...(form.kind === "Rating"
        ? [
            textFieldView(
              {
                id: `${events.id}-low`,
                label: message("question.lowLabel"),
                value: form.lowLabel,
                onInput: (value) => events.onField("lowLabel", value),
              },
              h,
            ),
            textFieldView(
              {
                id: `${events.id}-high`,
                label: message("question.highLabel"),
                value: form.highLabel,
                onInput: (value) => events.onField("highLabel", value),
              },
              h,
            ),
            Checkbox.view(
              {
                id: `${events.id}-comment`,
                isChecked: form.comment,
                onToggle: events.onComment,
                toView: (attributes) =>
                  h.div(
                    [h.Class("flex items-center gap-2 text-sm")],
                    [
                      h.button(
                        [...attributes.checkbox, h.Class("size-4 rounded border data-[checked]:bg-black")],
                        [],
                      ),
                      h.span(attributes.label, [message("question.comment")]),
                    ],
                  ),
              },
              h,
            ),
          ]
        : []),
      form.kind === "SingleChoice"
        ? Textarea.view(
            {
              id: `${events.id}-options`,
              value: form.options,
              rows: 4,
              onInput: (value) => events.onField("options", value),
              toView: (attributes) =>
                h.div(
                  [],
                  [
                    h.label([...attributes.label, h.Class(labelClass)], [message("question.options")]),
                    h.textarea([...attributes.textarea, h.Class(inputClass)], []),
                  ],
                ),
            },
            h,
          )
        : h.empty,
      form.kind === "LongText" ? h.p([h.Class(mutedClass)], [message("question.longText.help")]) : h.empty,
      selectFieldView(
        {
          id: `${events.id}-dimension`,
          label: message("question.dimension"),
          value: form.dimension,
          options: DIMENSIONS,
          onChange: events.onDimension,
        },
        h,
      ),
      changeProblemView(form.change, h),
      buttonView({ text: events.action, isSubmit: true, isDisabled: form.change._tag === "Busy" }, h),
    ],
  );

import {
  Dimension,
  PulseDetail,
  PulseId,
  type PulseQuestion,
  PulseSettings,
  type PulseWarning,
  QuestionContent,
  QuestionId,
  type QuestionType,
  TeamId,
  type TemplateQuestion,
  TemplateQuestionKey,
  Weekday,
} from "@surveybeat/domain";
import { Effect, Option, Record, Schema } from "effect";
import { AsyncData, Command, Submodel, type Update } from "foldkit";
import type { Html, HtmlBuilder } from "foldkit/html";
import { defineMessageUnion } from "foldkit/message";
import { defineTaggedUnion, taggedStruct } from "foldkit/schema";
import { modifyFields } from "foldkit/struct";
import { message, pluralMessage } from "../../messages/index.ts";
import { Failure, request } from "../api.ts";
import { Change, failedWith, type PageOutMessage } from "../change.ts";
import { pulsesRouter } from "../route.ts";
import {
  buttonClass,
  buttonView,
  changeProblemView,
  doneView,
  linkButtonClass,
  mutedClass,
  problemView,
  selectFieldView,
  textFieldView,
} from "../ui.ts";
import {
  contentOf,
  QuestionField,
  QuestionForm,
  questionForm,
  questionFormView,
  withDimension,
  withField,
  withKind,
} from "./questionForm.ts";

// MODEL

/** The settings as typed: plain strings until they are submitted. */
const SettingsForm = Schema.Struct({
  name: Schema.String,
  day: Schema.String,
  time: Schema.String,
  answerWindowDays: Schema.String,
  reminders: Schema.String,
});
type SettingsForm = typeof SettingsForm.Type;
const SettingField = Schema.Literals(["name", "day", "time", "answerWindowDays", "reminders"]);

/** The loaded editor. Changes answer with the whole Pulse, which replaces `detail`. */
const Editor = Schema.Struct({
  detail: PulseDetail,
  settings: SettingsForm,
  settingsChange: Change,
  /** Per Question: its move, remove, or edit buttons. */
  questionChanges: Schema.Record(Schema.String, Change),
  /** The Questions being rewritten, by id. */
  editing: Schema.Record(Schema.String, QuestionForm),
  /** The new Question being written, if any. */
  writing: Schema.Option(QuestionForm),
  templateChange: Change,
});
type Editor = typeof Editor.Type;

const Loaded = AsyncData.Schema(Editor, Failure);

/** The Pulse editor: Questions in order with the estimate and warnings, then the settings. */
export const Model = taggedStruct("PulsePage", {
  teamId: TeamId,
  pulseId: PulseId,
  editor: Loaded.schema,
});
export type Model = typeof Model.Type;

/** Which Question form a Message is about. */
export const FormTarget = defineTaggedUnion({
  Written: {},
  Edited: { questionId: QuestionId },
});
export type FormTarget = typeof FormTarget.Type;

// MESSAGE

export const Message = defineMessageUnion({
  SucceededLoadPulse: { detail: PulseDetail },
  FailedLoadPulse: { failure: Failure },

  UpdatedSetting: { field: SettingField, value: Schema.String },
  SubmittedSettings: {},
  SucceededSavePulseSettings: { detail: PulseDetail },
  FailedSavePulseSettings: { failure: Failure },

  ClickedMoveQuestion: { questionId: QuestionId, by: Schema.Literals([-1, 1]) },
  ClickedRemoveQuestion: { questionId: QuestionId },
  ClickedEditQuestion: { questionId: QuestionId },
  SucceededChangeQuestion: { questionId: QuestionId, detail: PulseDetail },
  FailedChangeQuestion: { questionId: QuestionId, failure: Failure },

  ClickedAddTemplateQuestion: { key: TemplateQuestionKey },
  SucceededAddTemplateQuestion: { detail: PulseDetail },
  FailedAddTemplateQuestion: { failure: Failure },

  ClickedWriteQuestion: {},
  UpdatedQuestionField: { target: FormTarget, field: QuestionField, value: Schema.String },
  SelectedQuestionKind: { target: FormTarget, value: Schema.String },
  SelectedQuestionDimension: { target: FormTarget, value: Schema.String },
  ToggledQuestionComment: { target: FormTarget, isChecked: Schema.Boolean },
  SubmittedQuestion: { target: FormTarget },
  SucceededSaveQuestion: { target: FormTarget, detail: PulseDetail },
  FailedSaveQuestion: { target: FormTarget, failure: Failure },
});
export type Message = typeof Message.Type;

// COMMAND

const pulseArgs = { teamId: TeamId, pulseId: PulseId };

export const LoadPulse = Command.define("LoadPulse", {
  args: pulseArgs,
  messages: [Message.SucceededLoadPulse, Message.FailedLoadPulse],
  execute: (params) =>
    request((api) => api.pulses.getPulse({ params })).pipe(
      Effect.match({
        onSuccess: (detail) => Message.SucceededLoadPulse({ detail }),
        onFailure: (failure) => Message.FailedLoadPulse({ failure }),
      }),
    ),
});

export const SavePulseSettings = Command.define("SavePulseSettings", {
  args: { ...pulseArgs, settings: PulseSettings },
  messages: [Message.SucceededSavePulseSettings, Message.FailedSavePulseSettings],
  execute: ({ settings, ...params }) =>
    request((api) => api.pulses.updatePulseSettings({ params, payload: settings })).pipe(
      Effect.match({
        onSuccess: (detail) => Message.SucceededSavePulseSettings({ detail }),
        onFailure: (failure) => Message.FailedSavePulseSettings({ failure }),
      }),
    ),
});

export const ReorderQuestions = Command.define("ReorderQuestions", {
  args: { ...pulseArgs, questionId: QuestionId, order: Schema.Array(QuestionId) },
  messages: [Message.SucceededChangeQuestion, Message.FailedChangeQuestion],
  execute: ({ questionId, order, ...params }) =>
    request((api) => api.pulses.reorderQuestions({ params, payload: { order } })).pipe(
      Effect.match({
        onSuccess: (detail) => Message.SucceededChangeQuestion({ questionId, detail }),
        onFailure: (failure) => Message.FailedChangeQuestion({ questionId, failure }),
      }),
    ),
});

export const RemoveQuestion = Command.define("RemoveQuestion", {
  args: { ...pulseArgs, questionId: QuestionId },
  messages: [Message.SucceededChangeQuestion, Message.FailedChangeQuestion],
  execute: ({ questionId, ...params }) =>
    request((api) => api.pulses.removeQuestion({ params: { ...params, questionId } })).pipe(
      Effect.match({
        onSuccess: (detail) => Message.SucceededChangeQuestion({ questionId, detail }),
        onFailure: (failure) => Message.FailedChangeQuestion({ questionId, failure }),
      }),
    ),
});

export const AddTemplateQuestion = Command.define("AddTemplateQuestion", {
  args: { ...pulseArgs, key: TemplateQuestionKey },
  messages: [Message.SucceededAddTemplateQuestion, Message.FailedAddTemplateQuestion],
  execute: ({ key, ...params }) =>
    request((api) => api.pulses.addQuestion({ params, payload: { _tag: "FromTemplate", key } })).pipe(
      Effect.match({
        onSuccess: (detail) => Message.SucceededAddTemplateQuestion({ detail }),
        onFailure: (failure) => Message.FailedAddTemplateQuestion({ failure }),
      }),
    ),
});

/** Adds the written Question, or rewrites the edited one. */
export const SaveQuestion = Command.define("SaveQuestion", {
  args: { ...pulseArgs, target: FormTarget, content: QuestionContent },
  messages: [Message.SucceededSaveQuestion, Message.FailedSaveQuestion],
  execute: ({ target, content, ...params }) =>
    request((api) =>
      FormTarget.match(target, {
        Written: () => api.pulses.addQuestion({ params, payload: { _tag: "Written", ...content } }),
        Edited: ({ questionId }) =>
          api.pulses.editQuestion({ params: { ...params, questionId }, payload: content }),
      }),
    ).pipe(
      Effect.match({
        onSuccess: (detail) => Message.SucceededSaveQuestion({ target, detail }),
        onFailure: (failure) => Message.FailedSaveQuestion({ target, failure }),
      }),
    ),
});

// INIT

export const init = (teamId: TeamId, pulseId: PulseId) => ({
  model: Model({ teamId, pulseId, editor: Loaded.Loading() }),
  commands: [LoadPulse({ teamId, pulseId })],
});

const editorFor = (detail: PulseDetail): Editor => ({
  detail,
  settings: {
    name: detail.settings.name,
    day: detail.settings.cadence.day,
    time: detail.settings.cadence.time,
    answerWindowDays: String(detail.settings.answerWindowDays),
    reminders: String(detail.settings.reminders),
  },
  settingsChange: Change.Idle(),
  questionChanges: {},
  editing: {},
  writing: Option.none(),
  templateChange: Change.Idle(),
});

// UPDATE

type UpdateReturn = Update.ReturnWithOutMessage<Model, Message, PageOutMessage>;

const decodeSettings = Schema.decodeUnknownOption(PulseSettings);
const isBusy = (change: Change | undefined) => change?._tag === "Busy";

/** Changes the loaded editor; before it has loaded, the Message changes nothing. */
const withEditor = (model: Model, change: (editor: Editor) => Editor): Model =>
  model.editor._tag === "Success"
    ? modifyFields(model, { editor: () => Loaded.Success({ data: change(editor(model)) }) })
    : model;

/** The loaded editor. Only called once `model.editor` is a Success. */
const editor = (model: Model): Editor => (model.editor._tag === "Success" ? model.editor.data : editorFor(emptyDetail));

const formOf = (current: Editor, target: FormTarget): Option.Option<QuestionForm> =>
  FormTarget.match(target, {
    Written: () => current.writing,
    Edited: ({ questionId }) => Record.get(current.editing, questionId),
  });

const withForm = (current: Editor, target: FormTarget, change: (form: QuestionForm) => QuestionForm): Editor =>
  FormTarget.match(target, {
    Written: () => ({ ...current, writing: Option.map(current.writing, change) }),
    Edited: ({ questionId }) =>
      Option.match(Record.get(current.editing, questionId), {
        onNone: () => current,
        onSome: (form) => ({ ...current, editing: Record.set(current.editing, questionId, change(form)) }),
      }),
  });

const closeForm = (current: Editor, target: FormTarget): Editor =>
  FormTarget.match(target, {
    Written: () => ({ ...current, writing: Option.none() }),
    Edited: ({ questionId }) => ({ ...current, editing: Record.remove(current.editing, questionId) }),
  });

const startQuestionChange = (model: Model, questionId: QuestionId, command: Command.Command<Message>): UpdateReturn =>
  model.editor._tag !== "Success" || isBusy(model.editor.data.questionChanges[questionId])
    ? { model }
    : {
        model: withEditor(model, (current) => ({
          ...current,
          questionChanges: Record.set(current.questionChanges, questionId, Change.Busy()),
        })),
        commands: [command],
      };

export const update = (model: Model, msg: Message) =>
  Message.match<UpdateReturn>(msg, {
    SucceededLoadPulse: ({ detail }) => ({
      model: modifyFields(model, { editor: () => Loaded.Success({ data: editorFor(detail) }) }),
    }),
    FailedLoadPulse: ({ failure }) =>
      failedWith(model, failure, (failure) => modifyFields(model, { editor: () => Loaded.Failure({ error: failure }) })),

    UpdatedSetting: ({ field, value }) => ({
      model: withEditor(model, (current) => ({ ...current, settings: { ...current.settings, [field]: value } })),
    }),
    SubmittedSettings: () => {
      if (model.editor._tag !== "Success") return { model };
      const current = model.editor.data;
      if (isBusy(current.settingsChange)) return { model };
      const { settings } = current;
      const parsed = decodeSettings({
        ...current.detail.settings,
        name: settings.name.trim(),
        cadence: { _tag: "Weekly", day: settings.day, time: settings.time },
        answerWindowDays: Number(settings.answerWindowDays),
        reminders: Number(settings.reminders),
      });
      if (Option.isNone(parsed)) {
        return {
          model: withEditor(model, (current) => ({
            ...current,
            settingsChange: Change.Failed({ failure: "Invalid" }),
          })),
        };
      }
      return {
        model: withEditor(model, (current) => ({ ...current, settingsChange: Change.Busy() })),
        commands: [SavePulseSettings({ teamId: model.teamId, pulseId: model.pulseId, settings: parsed.value })],
      };
    },
    SucceededSavePulseSettings: ({ detail }) => ({
      model: withEditor(model, (current) => ({ ...current, detail, settingsChange: Change.Done() })),
    }),
    FailedSavePulseSettings: ({ failure }) =>
      failedWith(model, failure, (failure) =>
        withEditor(model, (current) => ({ ...current, settingsChange: Change.Failed({ failure }) })),
      ),

    ClickedMoveQuestion: ({ questionId, by }) => {
      const order = editor(model).detail.questions.map((question) => question.questionId);
      const index = order.indexOf(questionId);
      const next = [...order];
      const [moved] = next.splice(index, 1);
      if (index === -1 || moved === undefined) return { model };
      next.splice(index + by, 0, moved);
      return startQuestionChange(
        model,
        questionId,
        ReorderQuestions({ teamId: model.teamId, pulseId: model.pulseId, questionId, order: next }),
      );
    },
    ClickedRemoveQuestion: ({ questionId }) =>
      startQuestionChange(model, questionId, RemoveQuestion({ teamId: model.teamId, pulseId: model.pulseId, questionId })),
    ClickedEditQuestion: ({ questionId }) => ({
      model: withEditor(model, (current) => {
        if (Record.has(current.editing, questionId)) {
          return { ...current, editing: Record.remove(current.editing, questionId) };
        }
        const question = current.detail.questions.find((each) => each.questionId === questionId);
        return question === undefined
          ? current
          : { ...current, editing: Record.set(current.editing, questionId, questionForm(question)) };
      }),
    }),
    SucceededChangeQuestion: ({ questionId, detail }) => ({
      model: withEditor(model, (current) => ({
        ...current,
        detail,
        questionChanges: Record.set(current.questionChanges, questionId, Change.Done()),
      })),
    }),
    FailedChangeQuestion: ({ questionId, failure }) =>
      failedWith(model, failure, (failure) =>
        withEditor(model, (current) => ({
          ...current,
          questionChanges: Record.set(current.questionChanges, questionId, Change.Failed({ failure })),
        })),
      ),

    ClickedAddTemplateQuestion: ({ key }) =>
      model.editor._tag !== "Success" || isBusy(model.editor.data.templateChange)
        ? { model }
        : {
            model: withEditor(model, (current) => ({ ...current, templateChange: Change.Busy() })),
            commands: [AddTemplateQuestion({ teamId: model.teamId, pulseId: model.pulseId, key })],
          },
    SucceededAddTemplateQuestion: ({ detail }) => ({
      model: withEditor(model, (current) => ({ ...current, detail, templateChange: Change.Done() })),
    }),
    FailedAddTemplateQuestion: ({ failure }) =>
      failedWith(model, failure, (failure) =>
        withEditor(model, (current) => ({ ...current, templateChange: Change.Failed({ failure }) })),
      ),

    ClickedWriteQuestion: () => ({
      model: withEditor(model, (current) => ({ ...current, writing: Option.some(questionForm()) })),
    }),
    UpdatedQuestionField: ({ target, field, value }) => ({
      model: withEditor(model, (current) => withForm(current, target, (form) => withField(form, field, value))),
    }),
    SelectedQuestionKind: ({ target, value }) => ({
      model: withEditor(model, (current) => withForm(current, target, (form) => withKind(form, value))),
    }),
    SelectedQuestionDimension: ({ target, value }) => ({
      model: withEditor(model, (current) => withForm(current, target, (form) => withDimension(form, value))),
    }),
    ToggledQuestionComment: ({ target, isChecked }) => ({
      model: withEditor(model, (current) => withForm(current, target, (form) => ({ ...form, comment: isChecked }))),
    }),
    SubmittedQuestion: ({ target }) => {
      if (model.editor._tag !== "Success") return { model };
      const form = formOf(model.editor.data, target);
      if (Option.isNone(form) || isBusy(form.value.change)) return { model };
      const content = contentOf(form.value);
      if (Option.isNone(content)) {
        return {
          model: withEditor(model, (current) =>
            withForm(current, target, (form) => ({ ...form, change: Change.Failed({ failure: "Invalid" }) })),
          ),
        };
      }
      return {
        model: withEditor(model, (current) =>
          withForm(current, target, (form) => ({ ...form, change: Change.Busy() })),
        ),
        commands: [SaveQuestion({ teamId: model.teamId, pulseId: model.pulseId, target, content: content.value })],
      };
    },
    SucceededSaveQuestion: ({ target, detail }) => ({
      model: withEditor(model, (current) => ({ ...closeForm(current, target), detail })),
    }),
    FailedSaveQuestion: ({ target, failure }) =>
      failedWith(model, failure, (failure) =>
        withEditor(model, (current) =>
          withForm(current, target, (form) => ({ ...form, change: Change.Failed({ failure }) })),
        ),
      ),
  });

// VIEW

const dimensionName = (dimension: Dimension | null) =>
  dimension === null ? message("dimension.none") : message(`dimension.${dimension}`);

const typeName = (type: QuestionType) => message(`questionType.${type._tag}`);

const warningMessage = (warning: PulseWarning): string => {
  switch (warning._tag) {
    case "TooManyQuestions":
      return message("pulse.warning.TooManyQuestions", warning);
    case "TooLong":
      return message("pulse.warning.TooLong", warning);
    case "NoOneTap":
      return message("pulse.warning.NoOneTap");
    case "TeamBelowMinimumGroupSize":
      return message("pulse.warning.TeamBelowMinimumGroupSize", warning);
  }
};

const WEEKDAYS = Weekday.literals.map((day) => [day, message(`weekday.${day}`)] as const);
const WINDOWS = [1, 2, 3, 4, 5, 6].map(
  (days) => [String(days), pluralMessage("pulse.settings.days", days)] as const,
);
const REMINDERS = [0, 1, 2].map(
  (count) => [String(count), pluralMessage("pulse.settings.reminderCount", count)] as const,
);

const formEvents = (target: FormTarget, id: string, title: string, action: string) => ({
  id,
  title,
  action,
  onField: (field: QuestionField, value: string) => Message.UpdatedQuestionField({ target, field, value }),
  onKind: (value: string) => Message.SelectedQuestionKind({ target, value }),
  onDimension: (value: string) => Message.SelectedQuestionDimension({ target, value }),
  onComment: (isChecked: boolean) => Message.ToggledQuestionComment({ target, isChecked }),
  onSubmit: Message.SubmittedQuestion({ target }),
});

const settingsView = (current: Editor, h: HtmlBuilder<Message>): Html => {
  const { settings, settingsChange } = current;
  const onSetting = (field: typeof SettingField.Type) => (value: string) =>
    Message.UpdatedSetting({ field, value });
  return h.form(
    [h.Class("mt-4 flex flex-col gap-3"), h.OnSubmit(Message.SubmittedSettings())],
    [
      h.h3([h.Class("text-lg font-medium")], [message("pulse.settings.title")]),
      textFieldView(
        { id: "pulse-name", label: message("pulse.settings.name"), value: settings.name, onInput: onSetting("name") },
        h,
      ),
      selectFieldView(
        {
          id: "pulse-day",
          label: message("pulse.settings.day"),
          value: settings.day,
          options: WEEKDAYS,
          onChange: onSetting("day"),
        },
        h,
      ),
      textFieldView(
        {
          id: "pulse-time",
          label: message("pulse.settings.time"),
          value: settings.time,
          onInput: onSetting("time"),
          type: "time",
        },
        h,
      ),
      h.p([h.Class(mutedClass)], [message("pulse.settings.time.help")]),
      selectFieldView(
        {
          id: "pulse-answer-window",
          label: message("pulse.settings.answerWindow"),
          value: settings.answerWindowDays,
          options: WINDOWS,
          onChange: onSetting("answerWindowDays"),
        },
        h,
      ),
      selectFieldView(
        {
          id: "pulse-reminders",
          label: message("pulse.settings.reminders"),
          value: settings.reminders,
          options: REMINDERS,
          onChange: onSetting("reminders"),
        },
        h,
      ),
      h.p([h.Class(mutedClass)], [message("pulse.settings.anonymous")]),
      h.p([h.Class(mutedClass)], [message("pulse.settings.invitation")]),
      changeProblemView(settingsChange, h),
      doneView(settingsChange, message("pulse.settings.saved"), h),
      buttonView(
        { text: message("pulse.settings.save"), isSubmit: true, isDisabled: isBusy(settingsChange) },
        h,
      ),
    ],
  );
};

const questionView = (
  current: Editor,
  question: PulseQuestion,
  index: number,
  h: HtmlBuilder<Message>,
): Html => {
  const { questionId } = question;
  const change = current.questionChanges[questionId] ?? Change.Idle();
  const busy = isBusy(change);
  const last = current.detail.questions.length - 1;
  return h.li(
    [h.Key(questionId), h.Class("rounded border px-3 py-2")],
    [
      h.p([], [`${message("pulse.question.number", { number: index + 1 })} ${question.text}`]),
      h.p(
        [h.Class(mutedClass)],
        [
          message("pulse.question.meta", {
            type: typeName(question.type),
            dimension: dimensionName(question.dimension),
            seconds: question.estimatedSeconds,
          }),
        ],
      ),
      h.div(
        [h.Class("mt-1 flex gap-4")],
        [
          buttonView(
            {
              text: message("pulse.question.up"),
              className: linkButtonClass,
              isDisabled: busy || index === 0,
              onClick: Message.ClickedMoveQuestion({ questionId, by: -1 }),
            },
            h,
          ),
          buttonView(
            {
              text: message("pulse.question.down"),
              className: linkButtonClass,
              isDisabled: busy || index === last,
              onClick: Message.ClickedMoveQuestion({ questionId, by: 1 }),
            },
            h,
          ),
          question.hasAnswers
            ? h.empty
            : buttonView(
                {
                  text: message("pulse.question.edit"),
                  className: linkButtonClass,
                  isDisabled: busy,
                  onClick: Message.ClickedEditQuestion({ questionId }),
                },
                h,
              ),
          buttonView(
            {
              text: message("pulse.question.remove"),
              className: linkButtonClass,
              isDisabled: busy,
              onClick: Message.ClickedRemoveQuestion({ questionId }),
            },
            h,
          ),
        ],
      ),
      question.hasAnswers ? h.p([h.Class(mutedClass)], [message("pulse.question.answered")]) : h.empty,
      changeProblemView(change, h),
      Option.match(Record.get(current.editing, questionId), {
        onNone: () => h.empty,
        onSome: (form) =>
          questionFormView(
            form,
            formEvents(
              FormTarget.Edited({ questionId }),
              `question-${questionId}`,
              message("pulse.question.edit"),
              message("pulse.question.save"),
            ),
            h,
          ),
      }),
    ],
  );
};

const templateView = (current: Editor, h: HtmlBuilder<Message>): Html => {
  const { templateQuestions } = current.detail;
  if (templateQuestions.length === 0) return h.empty;
  const templateQuestionView = (question: TemplateQuestion) =>
    h.li(
      [h.Key(question.key), h.Class("flex items-center justify-between rounded border px-3 py-2")],
      [
        h.span([], [`${question.text} `, h.span([h.Class(mutedClass)], [dimensionName(question.dimension)])]),
        buttonView(
          {
            text: message("pulse.template.add"),
            className: linkButtonClass,
            isDisabled: isBusy(current.templateChange),
            onClick: Message.ClickedAddTemplateQuestion({ key: question.key }),
          },
          h,
        ),
      ],
    );
  return h.div(
    [],
    [
      h.h3([h.Class("mt-6 text-lg font-medium")], [message("pulse.template.title")]),
      h.ul([h.Class("mt-2 flex flex-col gap-2")], templateQuestions.map(templateQuestionView)),
      changeProblemView(current.templateChange, h),
    ],
  );
};

const editorView = (current: Editor, h: HtmlBuilder<Message>): Html => {
  const { detail } = current;
  return h.div(
    [],
    [
      h.h2([h.Class("mt-2 text-xl font-semibold")], [detail.settings.name]),
      h.p([h.Class(mutedClass)], [detail.team.name]),
      h.p(
        [h.Class("mt-4"), h.Role("status")],
        [
          message("pulse.estimate", {
            questions: pluralMessage("pulse.questionCount", detail.questions.length),
            seconds: detail.estimatedSeconds,
          }),
        ],
      ),
      detail.warnings.length === 0
        ? h.empty
        : h.ul(
            [h.Class("mt-2 flex flex-col gap-1")],
            detail.warnings.map((warning) =>
              h.li(
                [h.Key(warning._tag), h.Class("rounded bg-amber-50 px-3 py-2 text-sm text-amber-900")],
                [warningMessage(warning)],
              ),
            ),
          ),
      h.h3([h.Class("mt-6 text-lg font-medium")], [message("pulse.questions")]),
      h.ol(
        [h.Class("mt-2 flex flex-col gap-2")],
        detail.questions.map((question, index) => questionView(current, question, index, h)),
      ),
      templateView(current, h),
      Option.match(current.writing, {
        onNone: () =>
          buttonView(
            {
              text: message("pulse.write.title"),
              className: `mt-4 ${buttonClass}`,
              onClick: Message.ClickedWriteQuestion(),
            },
            h,
          ),
        onSome: (form) =>
          questionFormView(
            form,
            formEvents(FormTarget.Written(), "write-question", message("pulse.write.title"), message("pulse.write.action")),
            h,
          ),
      }),
      settingsView(current, h),
    ],
  );
};

export const view = Submodel.defineView<Model, Message>((model, h) =>
  h.section(
    [h.Class("mt-6")],
    [
      h.a([h.Href(pulsesRouter({ teamId: model.teamId })), h.Class("text-sm underline")], [message("pulse.back")]),
      AsyncData.match(model.editor, {
        onIdle: () => h.empty,
        onLoading: () => h.empty,
        onRefreshing: (current) => editorView(current, h),
        onFailure: (failure) => problemView(failure, h),
        onStale: ({ data }) => editorView(data, h),
        onSuccess: (current) => editorView(current, h),
      }),
    ],
  ),
);

