input.content:
import { OrganizationId, OrganizationSummary, SessionState } from "@surveybeat/domain";
import { Effect, Option, Schema } from "effect";
import { Command, type Runtime, type Update } from "foldkit";
import type { Document, Html, HtmlBuilder } from "foldkit/html";
import { defineMessageUnion } from "foldkit/message";
import { load, pushUrl, UrlRequest } from "foldkit/navigation";
import { defineTaggedUnion } from "foldkit/schema";
import { modifyFields } from "foldkit/struct";
import { toString as urlToString, Url } from "foldkit/url";
import { message } from "../messages/index.ts";
import { Failure, request } from "./api.ts";
import { PageOutMessage } from "./change.ts";
import * as Pulse from "./page/pulse.ts";
import * as Pulses from "./page/pulses.ts";
import * as Settings from "./page/settings.ts";
import * as Team from "./page/team.ts";
import * as Teams from "./page/teams.ts";
import { AppRoute, pulseRouter, settingsRouter, teamRouter, teamsRouter, urlToAppRoute } from "./route.ts";
import { buttonClass, buttonView, signOutView, textFieldView } from "./ui.ts";

// MODEL

const Page = Schema.Union([Teams.Model, Team.Model, Settings.Model, Pulses.Model, Pulse.Model]);
type Page = typeof Page.Type;

/** What the app shows: the sign-in states until the session is in an Organization, then a page. */
export const Screen = defineTaggedUnion({
  Loading: {},
  SignedOut: {},
  Failed: {},
  CreateOrganization: { name: Schema.String, isBusy: Schema.Boolean },
  NotInOrganization: {},
  ChooseOrganization: { organizations: Schema.Array(OrganizationSummary), isBusy: Schema.Boolean },
  SignedIn: { organization: OrganizationSummary, organizationAdmin: Schema.Boolean, page: Page },
});
export type Screen = typeof Screen.Type;

export const Model = Schema.Struct({
  route: AppRoute,
  /** The sign-in callback sent the browser back with `?signin=failed`. */
  signInFailed: Schema.Boolean,
  /** The browser's time zone, the default for a new Team. */
  timeZone: Schema.String,
  screen: Screen,
});
export type Model = typeof Model.Type;

// MESSAGE

export const Message = defineMessageUnion({
  ClickedLink: { request: UrlRequest },
  ChangedUrl: { url: Url },
  CompletedNavigateInternal: {},
  CompletedLoadExternal: {},
  SucceededLoadSession: { state: SessionState },
  FailedLoadSession: { failure: Failure },
  ClickedRetry: {},
  UpdatedOrganizationName: { value: Schema.String },
  SubmittedCreateOrganization: {},
  SucceededCreateOrganization: { state: SessionState },
  FailedCreateOrganization: { failure: Failure },
  ClickedOrganization: { organizationId: OrganizationId },
  SucceededChooseOrganization: { state: SessionState },
  FailedChooseOrganization: { failure: Failure },
  GotTeamsMessage: { message: Teams.Message },
  GotTeamMessage: { message: Team.Message },
  GotSettingsMessage: { message: Settings.Message },
  GotPulsesMessage: { message: Pulses.Message },
  GotPulseMessage: { message: Pulse.Message },
});
export type Message = typeof Message.Type;

// COMMAND

export const NavigateInternal = Command.define("NavigateInternal", {
  args: { url: Schema.String },
  messages: [Message.CompletedNavigateInternal],
  execute: ({ url }) => pushUrl(url).pipe(Effect.as(Message.CompletedNavigateInternal())),
});

/** A full page load, for the paths the Worker serves: `/auth/login`. */
export const LoadExternal = Command.define("LoadExternal", {
  args: { href: Schema.String },
  messages: [Message.CompletedLoadExternal],
  execute: ({ href }) => load(href).pipe(Effect.as(Message.CompletedLoadExternal())),
});

export const LoadSession = Command.define("LoadSession", {
  messages: [Message.SucceededLoadSession, Message.FailedLoadSession],
  execute: request((api) => api.auth.session()).pipe(
    Effect.match({
      onSuccess: (state) => Message.SucceededLoadSession({ state }),
      onFailure: (failure) => Message.FailedLoadSession({ failure }),
    }),
  ),
});

export const CreateOrganization = Command.define("CreateOrganization", {
  args: { name: Schema.String },
  messages: [Message.SucceededCreateOrganization, Message.FailedCreateOrganization],
  execute: (payload) =>
    request((api) => api.auth.createOrganization({ payload })).pipe(
      Effect.match({
        onSuccess: (state) => Message.SucceededCreateOrganization({ state }),
        onFailure: (failure) => Message.FailedCreateOrganization({ failure }),
      }),
    ),
});

export const ChooseOrganization = Command.define("ChooseOrganization", {
  args: { organizationId: OrganizationId },
  messages: [Message.SucceededChooseOrganization, Message.FailedChooseOrganization],
  execute: (payload) =>
    request((api) => api.auth.chooseOrganization({ payload })).pipe(
      Effect.match({
        onSuccess: (state) => Message.SucceededChooseOrganization({ state }),
        onFailure: (failure) => Message.FailedChooseOrganization({ failure }),
      }),
    ),
});

// INIT

type UpdateReturn = Update.Return<Model, Message>;

export const init: Runtime.RoutingApplicationInit<Model, Message> = (url) => ({
  model: {
    route: urlToAppRoute(url),
    signInFailed: Option.exists(url.search, (search) => new URLSearchParams(search).get("signin") === "failed"),
    timeZone: Intl.DateTimeFormat().resolvedOptions().timeZone,
    screen: Screen.Loading(),
  },
  commands: [LoadSession()],
});

/** The page a route shows. Settings is for Organization admins only; anything else shows the Teams. */
const pageFor = (
  route: AppRoute,
  organizationAdmin: boolean,
  timeZone: string,
): { readonly page: Page; readonly commands: ReadonlyArray<Command.Command<Message>> } => {
  switch (route._tag) {
    case "Team": {
      const page = Team.init(route.teamId);
      return { page: page.model, commands: Command.mapMessages(page.commands, toTeam) };
    }
    case "Pulses": {
      const page = Pulses.init(route.teamId);
      return { page: page.model, commands: Command.mapMessages(page.commands, toPulses) };
    }
    case "Pulse": {
      const page = Pulse.init(route.teamId, route.pulseId);
      return { page: page.model, commands: Command.mapMessages(page.commands, toPulse) };
    }
    case "Settings":
      if (organizationAdmin) {
        const page = Settings.init();
        return { page: page.model, commands: Command.mapMessages(page.commands, toSettings) };
      }
      break;
    case "Teams":
    case "NotFound":
      break;
  }
  const page = Teams.init(organizationAdmin, timeZone);
  return { page: page.model, commands: Command.mapMessages(page.commands, toTeams) };
};

const toTeams = (message: Teams.Message) => Message.GotTeamsMessage({ message });
const toTeam = (message: Team.Message) => Message.GotTeamMessage({ message });
const toSettings = (message: Settings.Message) => Message.GotSettingsMessage({ message });
const toPulses = (message: Pulses.Message) => Message.GotPulsesMessage({ message });
const toPulse = (message: Pulse.Message) => Message.GotPulseMessage({ message });

// UPDATE

/** Shows what the session reports. A missing or revoked session shows the sign-in screen. */
const showSession = (model: Model, state: SessionState): UpdateReturn => {
  switch (state._tag) {
    case "CreateOrganization":
      return { model: modifyFields(model, { screen: () => Screen.CreateOrganization({ name: "", isBusy: false }) }) };
    case "NotInOrganization":
      return { model: modifyFields(model, { screen: () => Screen.NotInOrganization() }) };
    case "ChooseOrganization":
      return {
        model: modifyFields(model, {
          screen: () => Screen.ChooseOrganization({ organizations: state.organizations, isBusy: false }),
        }),
      };
    case "SignedIn": {
      const { page, commands } = pageFor(model.route, state.organizationAdmin, model.timeZone);
      return {
        model: modifyFields(model, {
          screen: () =>
            Screen.SignedIn({ organization: state.organization, organizationAdmin: state.organizationAdmin, page }),
        }),
        commands,
      };
    }
  }
};

const showFailure = (model: Model, failure: Failure): UpdateReturn => ({
  model: modifyFields(model, {
    screen: () => (failure === "Unauthenticated" ? Screen.SignedOut() : Screen.Failed()),
  }),
});

const reloadSession = (model: Model): UpdateReturn => ({
  model: modifyFields(model, { screen: () => Screen.Loading() }),
  commands: [LoadSession()],
});

/** Where a page's news leads: an ended session back to sign-in, a new Team or Pulse to its page. */
const followPage = (model: Model, outMessage: PageOutMessage): UpdateReturn =>
  PageOutMessage.match(outMessage, {
    EndedSession: () => reloadSession(model),
    CreatedTeam: ({ teamId }) => ({ model, commands: [NavigateInternal({ url: teamRouter({ teamId }) })] }),
    CreatedPulse: ({ teamId, pulseId }) => ({
      model,
      commands: [NavigateInternal({ url: pulseRouter({ teamId, pulseId }) })],
    }),
  });

/**
 * Hands a Message to the page it belongs to. A Message for a page that is no longer shown, such
 * as a load that finished after the user moved on, changes nothing.
 */
const foldPage = <ChildModel extends Page, ChildMessage>(
  model: Model,
  tag: ChildModel["_tag"],
  isPage: (page: Page) => page is ChildModel,
  childUpdate: (
    page: ChildModel,
    message: ChildMessage,
  ) => Update.ReturnWithOutMessage<ChildModel, ChildMessage, PageOutMessage>,
  toParent: (message: ChildMessage) => Message,
  childMessage: ChildMessage,
): UpdateReturn => {
  const screen = model.screen;
  if (screen._tag !== "SignedIn" || screen.page._tag !== tag || !isPage(screen.page)) return { model };
  const result = childUpdate(screen.page, childMessage);
  const next: UpdateReturn = {
    model: modifyFields(model, { screen: () => Screen.SignedIn({ ...screen, page: result.model }) }),
    commands: Command.mapMessages(result.commands ?? [], toParent),
  };
  if (result.outMessage === undefined) return next;
  const followed = followPage(next.model, result.outMessage);
  return { model: followed.model, commands: [...(next.commands ?? []), ...(followed.commands ?? [])] };
};

const isTeams = (page: Page): page is Teams.Model => page._tag === "TeamsPage";
const isTeam = (page: Page): page is Team.Model => page._tag === "TeamPage";
const isSettings = (page: Page): page is Settings.Model => page._tag === "SettingsPage";
const isPulses = (page: Page): page is Pulses.Model => page._tag === "PulsesPage";
const isPulse = (page: Page): page is Pulse.Model => page._tag === "PulsePage";

const sameRoute = Schema.toEquivalence(AppRoute);

export const update = (model: Model, msg: Message) =>
  Message.match<UpdateReturn>(msg, {
    ClickedLink: ({ request }) =>
      UrlRequest.match<UpdateReturn>(request, {
        // Paths outside the app, such as `/auth/login`, are the Worker's: load them.
        Internal: ({ url }) =>
          urlToAppRoute(url)._tag === "NotFound"
            ? { model, commands: [LoadExternal({ href: urlToString(url) })] }
            : { model, commands: [NavigateInternal({ url: urlToString(url) })] },
        External: ({ href }) => ({ model, commands: [LoadExternal({ href })] }),
      }),
    ChangedUrl: ({ url }) => {
      const route = urlToAppRoute(url);
      const screen = model.screen;
      if (sameRoute(route, model.route)) return { model };
      const routed = modifyFields(model, { route: () => route });
      if (screen._tag !== "SignedIn") return { model: routed };
      const { page, commands } = pageFor(route, screen.organizationAdmin, model.timeZone);
      return { model: modifyFields(routed, { screen: () => Screen.SignedIn({ ...screen, page }) }), commands };
    },
    CompletedNavigateInternal: () => ({ model }),
    CompletedLoadExternal: () => ({ model }),

    SucceededLoadSession: ({ state }) => showSession(model, state),
    FailedLoadSession: ({ failure }) => showFailure(model, failure),
    ClickedRetry: () => reloadSession(model),

    UpdatedOrganizationName: ({ value }) => ({
      model: modifyFields(model, {
        screen: (screen) => (screen._tag === "CreateOrganization" ? { ...screen, name: value } : screen),
      }),
    }),
    SubmittedCreateOrganization: () => {
      const screen = model.screen;
      if (screen._tag !== "CreateOrganization" || screen.isBusy || screen.name.trim() === "") return { model };
      return {
        model: modifyFields(model, { screen: () => ({ ...screen, isBusy: true }) }),
        commands: [CreateOrganization({ name: screen.name.trim() })],
      };
    },
    SucceededCreateOrganization: ({ state }) => showSession(model, state),
    FailedCreateOrganization: ({ failure }) => showFailure(model, failure),

    ClickedOrganization: ({ organizationId }) => {
      const screen = model.screen;
      if (screen._tag !== "ChooseOrganization" || screen.isBusy) return { model };
      return {
        model: modifyFields(model, { screen: () => ({ ...screen, isBusy: true }) }),
        commands: [ChooseOrganization({ organizationId })],
      };
    },
    SucceededChooseOrganization: ({ state }) => showSession(model, state),
    FailedChooseOrganization: ({ failure }) => showFailure(model, failure),

    GotTeamsMessage: ({ message }) => foldPage(model, "TeamsPage", isTeams, Teams.update, toTeams, message),
    GotTeamMessage: ({ message }) => foldPage(model, "TeamPage", isTeam, Team.update, toTeam, message),
    GotSettingsMessage: ({ message }) =>
      foldPage(model, "SettingsPage", isSettings, Settings.update, toSettings, message),
    GotPulsesMessage: ({ message }) => foldPage(model, "PulsesPage", isPulses, Pulses.update, toPulses, message),
    GotPulseMessage: ({ message }) => foldPage(model, "PulsePage", isPulse, Pulse.update, toPulse, message),
  });

// VIEW

const screenView = (title: string, children: ReadonlyArray<Html>, h: HtmlBuilder<Message>): Html =>
  h.main([h.Class("mx-auto max-w-xl p-6")], [h.h1([h.Class("text-2xl font-semibold")], [title]), ...children]);

const introView = (text: string, h: HtmlBuilder<Message>): Html => h.p([h.Class("mt-2 text-gray-600")], [text]);

const signInView = (model: Model, h: HtmlBuilder<Message>): Html =>
  screenView(
    message("signIn.title"),
    [
      introView(message("signIn.intro"), h),
      model.signInFailed ? h.p([h.Role("alert"), h.Class("mt-2 text-red-700")], [message("signIn.failed")]) : h.empty,
      // A link styled and announced as a button: AuthKit's hosted page is a full page load.
      h.a(
        [h.Href("/auth/login"), h.Role("button"), h.Class(`mt-4 inline-block ${buttonClass}`)],
        [message("signIn.action")],
      ),
    ],
    h,
  );

const createOrganizationView = (name: string, isBusy: boolean, h: HtmlBuilder<Message>): Html =>
  screenView(
    message("createOrganization.title"),
    [
      introView(message("createOrganization.intro"), h),
      h.form(
        [h.Class("mt-4 flex flex-col gap-3"), h.OnSubmit(Message.SubmittedCreateOrganization())],
        [
          textFieldView(
            {
              id: "organization-name",
              label: message("createOrganization.name"),
              value: name,
              maxLength: 100,
              onInput: (value) => Message.UpdatedOrganizationName({ value }),
            },
            h,
          ),
          buttonView(
            { text: message("createOrganization.action"), isSubmit: true, isDisabled: isBusy || name.trim() === "" },
            h,
          ),
        ],
      ),
      signOutView(h),
    ],
    h,
  );

const chooseOrganizationView = (
  organizations: ReadonlyArray<OrganizationSummary>,
  isBusy: boolean,
  h: HtmlBuilder<Message>,
): Html =>
  screenView(
    message("chooseOrganization.title"),
    [
      introView(message("chooseOrganization.intro"), h),
      h.ul(
        [h.Class("mt-4 flex flex-col gap-2")],
        organizations.map((organization) =>
          h.li(
            [h.Key(organization.id)],
            [
              buttonView(
                {
                  text: organization.name,
                  className: `w-full text-left ${buttonClass}`,
                  isDisabled: isBusy,
                  onClick: Message.ClickedOrganization({ organizationId: organization.id }),
                },
                h,
              ),
            ],
          ),
        ),
      ),
      signOutView(h),
    ],
    h,
  );

const pageView = (page: Page, h: HtmlBuilder<Message>): Html => {
  switch (page._tag) {
    case "TeamsPage":
      return h.submodel({ slotId: "teams", model: page, view: Teams.view, toParentMessage: toTeams });
    case "TeamPage":
      return h.submodel({ slotId: "team", model: page, view: Team.view, toParentMessage: toTeam });
    case "SettingsPage":
      return h.submodel({ slotId: "settings", model: page, view: Settings.view, toParentMessage: toSettings });
    case "PulsesPage":
      return h.submodel({ slotId: "pulses", model: page, view: Pulses.view, toParentMessage: toPulses });
    case "PulsePage":
      return h.submodel({ slotId: "pulse", model: page, view: Pulse.view, toParentMessage: toPulse });
  }
};

/** The signed-in frame: heading, navigation, the page, and sign out. */
const signedInView = (
  organization: OrganizationSummary,
  organizationAdmin: boolean,
  page: Page,
  h: HtmlBuilder<Message>,
): Html =>
  screenView(
    message("signedIn.title", { organization: organization.name }),
    [
      h.nav(
        [h.Class("mt-4 flex gap-4")],
        [
          h.a([h.Href(teamsRouter()), h.Class("underline")], [message("nav.teams")]),
          organizationAdmin
            ? h.a([h.Href(settingsRouter()), h.Class("underline")], [message("nav.settings")])
            : h.empty,
        ],
      ),
      pageView(page, h),
      signOutView(h),
    ],
    h,
  );

export const view = (model: Model, h: HtmlBuilder<Message>): Document => ({
  title: message("app.title"),
  body: Screen.match(model.screen, {
    Loading: () => screenView(message("app.loading"), [], h),
    SignedOut: () => signInView(model, h),
    Failed: () =>
      screenView(
        message("app.error"),
        [buttonView({ text: message("app.retry"), className: `mt-4 ${buttonClass}`, onClick: Message.ClickedRetry() }, h)],
        h,
      ),
    CreateOrganization: ({ name, isBusy }) => createOrganizationView(name, isBusy, h),
    NotInOrganization: () =>
      screenView(message("notInOrganization.title"), [introView(message("notInOrganization.intro"), h), signOutView(h)], h),
