// Test data for the story and scene tests. Never imported by the app.
import {
  EmailAddress,
  OrganizationId,
  type OrganizationSettings,
  type OrganizationSummary,
  PersonId,
  PulseId,
  type PulseDetail,
  type PulseList,
  type PulseQuestion,
  QuestionId,
  QuestionVersionId,
  SendTime,
  type TeamDetail,
  TeamId,
  type TeamSummary,
  TimeZone,
  WEEKLY_TEAM_HEALTH,
} from "@surveybeat/domain";

export const organization: OrganizationSummary = { id: OrganizationId.make("org1"), name: "Acme" };
export const otherOrganization: OrganizationSummary = { id: OrganizationId.make("org2"), name: "Globex" };

export const teamId = TeamId.make("team1");
export const pulseId = PulseId.make("pulse1");
export const leadId = PersonId.make("person1");
export const memberId = PersonId.make("person2");

export const team: TeamSummary = {
  id: teamId,
  name: "Platform",
  timeZone: TimeZone.make("Europe/Berlin"),
  yourRole: "lead",
};

export const teamDetail: TeamDetail = {
  team,
  roster: [
    { personId: leadId, email: EmailAddress.make("lea@example.com"), role: "lead", since: Date.UTC(2026, 0, 5) },
    { personId: memberId, email: EmailAddress.make("max@example.com"), role: "member", since: Date.UTC(2026, 1, 2) },
  ],
  may: { update: true, manageLeads: true, manageMembers: true, managePulses: true, viewResults: true },
};

export const settings: OrganizationSettings = {
  name: "Acme",
  minimumGroupSize: 4,
  people: [
    { personId: leadId, email: EmailAddress.make("lea@example.com"), organizationAdmin: true, linked: true },
    { personId: memberId, email: EmailAddress.make("max@example.com"), organizationAdmin: false, linked: false },
  ],
};

const cadence = { _tag: "Weekly", day: "monday", time: SendTime.make("09:00") } as const;

export const pulseList: PulseList = {
  team,
  pulses: [{ id: pulseId, name: "Weekly check-in", cadence, questionCount: 2, estimatedSeconds: 20 }],
};

const question = (id: string, index: number, hasAnswers = false): PulseQuestion => {
  const template = WEEKLY_TEAM_HEALTH.questions[index];
  if (template === undefined) throw new Error(`no Template Question ${index}`);
  const { key, ...content } = template;
  const questionId = QuestionId.make(id);
  return {
    questionId,
    versionId: QuestionVersionId.make(`${id}.1`),
    templateKey: key,
    ...content,
    hasAnswers,
    estimatedSeconds: 10,
  };
};

export const firstQuestion = question("q1", 0);
export const secondQuestion = question("q2", 2, true);

export const pulseDetail: PulseDetail = {
  id: pulseId,
  team,
  settings: {
    name: "Weekly check-in",
    cadence,
    answerWindowDays: 2,
    reminders: 1,
    anonymityMode: "anonymous",
    distribution: "invitation",
  },
  questions: [firstQuestion, secondQuestion],
  estimatedSeconds: 20,
  warnings: [{ _tag: "NoOneTap" }],
  templateQuestions: WEEKLY_TEAM_HEALTH.questions.slice(1, 2),
};

import { Option } from "effect";
import { Command, given, message, model, story } from "foldkit/story";
import { describe, expect, test } from "vitest";
import { organization, otherOrganization, teamDetail, teamId, team } from "./fixtures.ts";
import {
  ChooseOrganization,
  CreateOrganization,
  init,
  LoadExternal,
  LoadSession,
  Message,
  type Model,
  NavigateInternal,
  Screen,
  update,
} from "./main.ts";
import * as Settings from "./page/settings.ts";
import * as Team from "./page/team.ts";
import * as Teams from "./page/teams.ts";
import { AppRoute, teamRouter } from "./route.ts";

const url = (pathname: string, search?: string) => ({
  protocol: "https:",
  host: "app.surveybeat.app",
  port: Option.none(),
  pathname,
  search: Option.fromUndefinedOr(search),
  hash: Option.none(),
});

const loading: Model = { route: AppRoute.Teams(), signInFailed: false, timeZone: "UTC", screen: Screen.Loading() };
const signedIn = (organizationAdmin: boolean) =>
  Message.SucceededLoadSession({
    state: { _tag: "SignedIn", organization, personId: teamDetail.roster[0]!.personId, organizationAdmin },
  });

describe("init", () => {
  test("loads the session and remembers a failed sign-in", () => {
    const started = init(url("/", "?signin=failed"));
    expect(started.model.screen._tag).toBe("Loading");
    expect(started.model.signInFailed).toBe(true);
    expect(started.commands?.map((command) => command.name)).toEqual(["LoadSession"]);
  });

  test("parses the route from the path", () => {
    expect(init(url(`/teams/${teamId}`)).model.route).toEqual(AppRoute.Team({ teamId }));
    expect(init(url("/settings")).model.route).toEqual(AppRoute.Settings());
    expect(init(url("/nowhere")).model.route._tag).toBe("NotFound");
  });
});

describe("sign-in states", () => {
  test("a missing session shows the sign-in screen, anything else the error", () => {
    story(
      update,
      given(loading),
      message(Message.FailedLoadSession({ failure: "Unauthenticated" })),
      model((next) => expect(next.screen._tag).toBe("SignedOut")),
      message(Message.FailedLoadSession({ failure: "Unavailable" })),
      model((next) => expect(next.screen._tag).toBe("Failed")),
      message(Message.ClickedRetry()),
      model((next) => expect(next.screen._tag).toBe("Loading")),
      Command.resolve(LoadSession, Message.SucceededLoadSession({ state: { _tag: "NotInOrganization" } })),
      model((next) => expect(next.screen._tag).toBe("NotInOrganization")),
    );
  });

  test("creates an Organization with the trimmed name and enters it", () => {
    story(
      update,
      given(loading),
      message(Message.SucceededLoadSession({ state: { _tag: "CreateOrganization" } })),
      message(Message.SubmittedCreateOrganization()),
      Command.expectNone(),
      message(Message.UpdatedOrganizationName({ value: "  Acme  " })),
      message(Message.SubmittedCreateOrganization()),
      model((next) => expect(next.screen).toEqual(Screen.CreateOrganization({ name: "  Acme  ", isBusy: true }))),
      Command.expectExact(CreateOrganization({ name: "Acme" })),
      message(Message.SubmittedCreateOrganization()),
      Command.resolve(CreateOrganization, signedIn(true).pipe ? signedIn(true) : signedIn(true)),
      model((next) => expect(next.screen._tag).toBe("SignedIn")),
      Command.resolve(Teams.LoadTeams, Teams.Message.SucceededLoadTeams({ teams: [team] })),
    );
  });

  test("picks one of several Organizations", () => {
    story(
      update,
      given(loading),
      message(
        Message.SucceededLoadSession({
          state: { _tag: "ChooseOrganization", organizations: [organization, otherOrganization] },
        }),
      ),
      message(Message.ClickedOrganization({ organizationId: otherOrganization.id })),
      message(Message.ClickedOrganization({ organizationId: organization.id })),
      Command.expectExact(ChooseOrganization({ organizationId: otherOrganization.id })),
      Command.resolve(ChooseOrganization, Message.FailedChooseOrganization({ failure: "Unauthenticated" })),
      model((next) => expect(next.screen._tag).toBe("SignedOut")),
    );
  });
});

describe("routing", () => {
  test("a signed-in session opens the page of the current route", () => {
    story(
      update,
      given({ ...loading, route: AppRoute.Team({ teamId }) }),
      message(signedIn(false)),
      model((next) => {
        expect(next.screen._tag === "SignedIn" && next.screen.page._tag).toBe("TeamPage");
      }),
      Command.resolve(Team.LoadTeam, Team.Message.SucceededLoadTeam({ detail: teamDetail })),
    );
  });

  test("Organization settings are for admins only; others see the Teams", () => {
    story(
      update,
      given({ ...loading, route: AppRoute.Settings() }),
      message(signedIn(false)),
      model((next) => expect(next.screen._tag === "SignedIn" && next.screen.page._tag).toBe("TeamsPage")),
      Command.resolve(Teams.LoadTeams, Teams.Message.SucceededLoadTeams({ teams: [] })),
    );
    story(
      update,
      given({ ...loading, route: AppRoute.Settings() }),
      message(signedIn(true)),
      model((next) => expect(next.screen._tag === "SignedIn" && next.screen.page._tag).toBe("SettingsPage")),
      Command.expectExact(Settings.LoadSettings()),
      Command.resolve(Settings.LoadSettings, Settings.Message.FailedLoadSettings({ failure: "Forbidden" })),
    );
  });

  test("links inside the app push the URL; the Worker's paths load in full", () => {
    const appUrl = url(`/teams/${teamId}`);
    const loginUrl = url("/auth/login");
    story(
      update,
      given(loading),
      message(Message.ClickedLink({ request: { _tag: "Internal", url: appUrl } })),
      Command.expectExact(NavigateInternal({ url: `/teams/${teamId}` })),
      Command.resolve(NavigateInternal, Message.CompletedNavigateInternal()),
      message(Message.ClickedLink({ request: { _tag: "Internal", url: loginUrl } })),
      Command.expectExact(LoadExternal({ href: "https://app.surveybeat.app/auth/login" })),
      Command.resolve(LoadExternal, Message.CompletedLoadExternal()),
    );
  });

  test("a changed URL opens its page; the same URL keeps the page", () => {
    story(
      update,
      given(loading),
      message(signedIn(false)),
      Command.resolve(Teams.LoadTeams, Teams.Message.SucceededLoadTeams({ teams: [team] })),
      message(Message.ChangedUrl({ url: url(`/teams/${teamId}`) })),
      model((next) => expect(next.route).toEqual(AppRoute.Team({ teamId }))),
      Command.resolve(Team.LoadTeam, Team.Message.SucceededLoadTeam({ detail: teamDetail })),
      message(Message.ChangedUrl({ url: url(`/teams/${teamId}`) })),
      Command.expectNone(),
    );
  });
});

describe("pages", () => {
  test("an ended session goes back to sign-in", () => {
    story(
      update,
      given(loading),
      message(signedIn(false)),
      Command.resolve(Teams.LoadTeams, Teams.Message.FailedLoadTeams({ failure: "Unauthenticated" })),
      model((next) => expect(next.screen._tag).toBe("Loading")),
      Command.resolve(LoadSession, Message.FailedLoadSession({ failure: "Unauthenticated" })),
      model((next) => expect(next.screen._tag).toBe("SignedOut")),
    );
  });

  test("a new Team opens its page", () => {
    story(
      update,
      given(loading),
      message(signedIn(true)),
      Command.resolve(Teams.LoadTeams, Teams.Message.SucceededLoadTeams({ teams: [] })),
      message(Message.GotTeamsMessage({ message: Teams.Message.SucceededCreateTeam({ teamId }) })),
      Command.expectExact(NavigateInternal({ url: teamRouter({ teamId }) })),
      Command.resolve(NavigateInternal, Message.CompletedNavigateInternal()),
    );
  });

  test("a result for a page no longer shown changes nothing", () => {
    story(
      update,
      given(loading),
      message(signedIn(false)),
      Command.resolve(Teams.LoadTeams, Teams.Message.SucceededLoadTeams({ teams: [] })),
      message(Message.GotTeamMessage({ message: Team.Message.SucceededLoadTeam({ detail: teamDetail }) })),
      model((next) => expect(next.screen._tag === "SignedIn" && next.screen.page._tag).toBe("TeamsPage")),
    );
  });
});

