import { Command, click, expect, given, label, role, scene, submit, text, type } from "foldkit/scene";
import { describe, test } from "vitest";
import { message } from "../messages/index.ts";
import { organization, otherOrganization, team } from "./fixtures.ts";
import { ChooseOrganization, CreateOrganization, LoadSession, Message, type Model, Screen, update, view } from "./main.ts";
import * as Teams from "./page/teams.ts";
import { AppRoute } from "./route.ts";

const at = (screen: Screen, signInFailed = false): Model => ({
  route: AppRoute.Teams(),
  signInFailed,
  timeZone: "UTC",
  screen,
});

const app = { update, view };

describe("sign-in screens", () => {
  test("signed out: a sign-in button, and the failure after a failed callback", () => {
    scene(
      app,
      given(at(Screen.SignedOut())),
      expect(role("heading", { level: 1, name: message("signIn.title") })).toExist(),
      expect(role("button", { name: message("signIn.action") })).toHaveAttr("href", "/auth/login"),
      expect(role("alert")).toBeAbsent(),
    );
    scene(app, given(at(Screen.SignedOut(), true)), expect(role("alert")).toHaveText(message("signIn.failed")));
  });

  test("an error offers to try again", () => {
    scene(
      app,
      given(at(Screen.Failed())),
      expect(role("heading", { name: message("app.error") })).toExist(),
