import { PulseId, SendTime, TemplateQuestionKey } from "@surveybeat/domain";
import { Option } from "effect";
import { Command, expectOutMessage, given, message, model, story } from "foldkit/story";
import { describe, expect, test } from "vitest";
import { PageOutMessage } from "../change.ts";
import { firstQuestion, pulseDetail, pulseId, secondQuestion, teamId } from "../fixtures.ts";
import {
  AddTemplateQuestion,
  FormTarget,
  init,
  Message,
  type Model,
  RemoveQuestion,
  ReorderQuestions,
  SavePulseSettings,
  SaveQuestion,
  update,
} from "./pulse.ts";

const loaded = update(init(teamId, pulseId).model, Message.SucceededLoadPulse({ detail: pulseDetail })).model;
const editorOf = (model: Model) => {
  if (model.editor._tag !== "Success") throw new Error("not loaded");
  return model.editor.data;
};
const reordered = { ...pulseDetail, questions: [secondQuestion, firstQuestion] };

describe("Pulse editor", () => {
  test("loads the Pulse and fills the settings form", () => {
    expect(editorOf(loaded).settings).toEqual({
      name: "Weekly check-in",
      day: "monday",
      time: "09:00",
      answerWindowDays: "2",
      reminders: "1",
    });
  });

  test("moves a Question down with the full new order", () => {
    story(
      update,
      given(loaded),
      message(Message.ClickedMoveQuestion({ questionId: firstQuestion.questionId, by: 1 })),
      model((next) => expect(editorOf(next).questionChanges[firstQuestion.questionId]?._tag).toBe("Busy")),
      Command.expectExact(
        ReorderQuestions({
          teamId,
          pulseId,
          questionId: firstQuestion.questionId,
          order: [secondQuestion.questionId, firstQuestion.questionId],
        }),
      ),
      Command.resolve(
        ReorderQuestions,
        Message.SucceededChangeQuestion({ questionId: firstQuestion.questionId, detail: reordered }),
      ),
      model((next) => expect(editorOf(next).detail.questions[0]).toEqual(secondQuestion)),
    );
  });

  test("the last Question can't be removed: the refusal shows on it", () => {
    story(
      update,
      given(loaded),
      message(Message.ClickedRemoveQuestion({ questionId: secondQuestion.questionId })),
      Command.expectExact(RemoveQuestion({ teamId, pulseId, questionId: secondQuestion.questionId })),
      Command.resolve(
        RemoveQuestion,
        Message.FailedChangeQuestion({ questionId: secondQuestion.questionId, failure: "PulseNeedsAQuestion" }),
      ),
      model((next) =>
        expect(editorOf(next).questionChanges[secondQuestion.questionId]).toEqual({
          _tag: "Failed",
          failure: "PulseNeedsAQuestion",
        }),
      ),
    );
  });

  test("adds a Template Question", () => {
    const key = TemplateQuestionKey.make("safe-to-speak-up");
    story(
      update,
      given(loaded),
      message(Message.ClickedAddTemplateQuestion({ key })),
      Command.expectExact(AddTemplateQuestion({ teamId, pulseId, key })),
      Command.resolve(AddTemplateQuestion, Message.SucceededAddTemplateQuestion({ detail: pulseDetail })),
      model((next) => expect(editorOf(next).templateChange._tag).toBe("Done")),
    );
  });

  test("writes a single choice Question: options are one per line, trimmed", () => {
    const target = FormTarget.Written();
    story(
      update,
      given(loaded),
      message(Message.ClickedWriteQuestion()),
      message(Message.UpdatedQuestionField({ target, field: "text", value: " Where do you work? " })),
      message(Message.SelectedQuestionKind({ target, value: "SingleChoice" })),
      message(Message.UpdatedQuestionField({ target, field: "options", value: "Office\n\n Home \n" })),
      message(Message.SelectedQuestionDimension({ target, value: "workload" })),
      message(Message.SubmittedQuestion({ target })),
      Command.expectExact(
        SaveQuestion({
          teamId,
          pulseId,
          target,
          content: {
            text: "Where do you work?",
            dimension: "workload",
            type: { _tag: "SingleChoice", options: ["Office", "Home"] },
          },
        }),
      ),
      Command.resolve(SaveQuestion, Message.SucceededSaveQuestion({ target, detail: pulseDetail })),
      model((next) => expect(editorOf(next).writing).toEqual(Option.none())),
    );
  });

  test("an incomplete Question fails without a call", () => {
    const target = FormTarget.Written();
    story(
      update,
      given(loaded),
      message(Message.ClickedWriteQuestion()),
      message(Message.UpdatedQuestionField({ target, field: "text", value: "Rate it" })),
      message(Message.SubmittedQuestion({ target })),
      Command.expectNone(),
      model((next) =>
        expect(Option.map(editorOf(next).writing, (form) => form.change)).toEqual(
          Option.some({ _tag: "Failed", failure: "Invalid" }),
        ),
      ),
    );
  });

  test("edits a Question in place and closes the form", () => {
    const target = FormTarget.Edited({ questionId: firstQuestion.questionId });
    story(
      update,
      given(loaded),
      message(Message.ClickedEditQuestion({ questionId: firstQuestion.questionId })),
      model((next) => expect(editorOf(next).editing[firstQuestion.questionId]?.text).toBe(firstQuestion.text)),
      message(Message.ToggledQuestionComment({ target, isChecked: false })),
      message(Message.SubmittedQuestion({ target })),
      Command.expectHas(SaveQuestion),
      Command.resolve(SaveQuestion, Message.SucceededSaveQuestion({ target, detail: pulseDetail })),
      model((next) => expect(editorOf(next).editing).toEqual({})),
    );
  });

  test("saves the settings", () => {
    story(
      update,
      given(loaded),
      message(Message.UpdatedSetting({ field: "day", value: "friday" })),
      message(Message.UpdatedSetting({ field: "reminders", value: "2" })),
      message(Message.SubmittedSettings()),
      Command.expectExact(
        SavePulseSettings({
          teamId,
          pulseId,
          settings: {
            ...pulseDetail.settings,
            cadence: { _tag: "Weekly", day: "friday", time: SendTime.make("09:00") },
            reminders: 2,
          },
        }),
      ),
      Command.resolve(SavePulseSettings, Message.SucceededSavePulseSettings({ detail: pulseDetail })),
      model((next) => expect(editorOf(next).settingsChange._tag).toBe("Done")),
    );
  });

  test("a send time at night fails without a call", () => {
    story(
      update,
      given(loaded),
      message(Message.UpdatedSetting({ field: "time", value: "23:00" })),
      message(Message.SubmittedSettings()),
      Command.expectNone(),
      model((next) => expect(editorOf(next).settingsChange).toEqual({ _tag: "Failed", failure: "Invalid" })),
    );
  });

  test("an ended session goes up; another Pulse's late result changes nothing", () => {
    story(
      update,
      given(loaded),
      message(Message.FailedSavePulseSettings({ failure: "Unauthenticated" })),
      expectOutMessage(PageOutMessage.EndedSession()),
    );
    const other = { ...pulseDetail, id: PulseId.make("pulse2") };
    expect(update(init(teamId, pulseId).model, Message.SucceededLoadPulse({ detail: other })).model.editor._tag).toBe(
      "Loading",
    );
  });
});
