cat > pulse.scene.test.ts <<'EOF'
import { Command, change, click, expect, given, label, role, scene, submit, text, type } from "foldkit/scene";
import { describe, test } from "vitest";
import { message, pluralMessage } from "../../messages/index.ts";
import { firstQuestion, pulseDetail, pulseId, secondQuestion, teamId } from "../fixtures.ts";
import { FormTarget, init, Message, ReorderQuestions, SavePulseSettings, SaveQuestion, update, view } from "./pulse.ts";

const page = { update, view };
const loaded = update(init(teamId, pulseId).model, Message.SucceededLoadPulse({ detail: pulseDetail })).model;

describe("Pulse editor", () => {
  test("shows the estimate, the warnings, the Questions in order, and the Template", () => {
    scene(
      page,
      given(loaded),
      expect(role("heading", { level: 2, name: "Weekly check-in" })).toExist(),
      expect(role("status")).toHaveText(
        message("pulse.estimate", { questions: pluralMessage("pulse.questionCount", 2), seconds: 20 }),
      ),
      expect(text(message("pulse.warning.NoOneTap"))).toExist(),
      expect(text(`1. ${firstQuestion.text}`)).toExist(),
      expect(text(`2. ${secondQuestion.text}`)).toExist(),
      expect(text(message("pulse.question.answered"))).toExist(),
      expect(role("heading", { name: message("pulse.template.title") })).toExist(),
      expect(role("link", { name: message("pulse.back") })).toHaveAttr("href", `/teams/${teamId}/pulses`),
    );
  });

  test("the first Question can't move up; moving it down sends the new order", () => {
    scene(
      page,
      given(loaded),
      expect(role("button", { name: message("pulse.question.up") })).toBeDisabled(),
      click(role("button", { name: message("pulse.question.down") })),
      Command.resolve(
        ReorderQuestions,
        Message.SucceededChangeQuestion({
          questionId: firstQuestion.questionId,
          detail: { ...pulseDetail, questions: [secondQuestion, firstQuestion] },
        }),
      ),
      expect(text(`1. ${secondQuestion.text}`)).toExist(),
    );
  });

  test("writes a Question: the fields follow the type", () => {
    scene(
      page,
      given(loaded),
      click(role("button", { name: message("pulse.write.title") })),
      expect(label(message("question.lowLabel"))).toExist(),
      expect(role("checkbox", { name: message("question.comment") })).toBeChecked(),
      change(label(message("question.type")), "LongText"),
      expect(label(message("question.lowLabel"))).toBeAbsent(),
      expect(text(message("question.longText.help"))).toExist(),
      type(label(message("question.text")), "Anything else?"),
      click(role("button", { name: message("pulse.write.action") })),
      submit(role("form", { name: undefined })),
      Command.resolve(
        SaveQuestion,
        Message.SucceededSaveQuestion({ target: FormTarget.Written(), detail: pulseDetail }),
      ),
      expect(role("button", { name: message("pulse.write.action") })).toBeAbsent(),
    );
  });

  test("saving the settings says Saved", () => {
    scene(
      page,
      given(loaded),
      change(label(message("pulse.settings.day")), "friday"),
      expect(label(message("pulse.settings.day"))).toHaveValue("friday"),
      click(role("button", { name: message("pulse.settings.save") })),
      Command.resolve(SavePulseSettings, Message.SucceededSavePulseSettings({ detail: pulseDetail })),
      expect(text(message("pulse.settings.saved"))).toExist(),
    );
  });
});
EOF
