let signedIn = process.env.SIGNED_IN !== "0";
const calls = [];
const team = { id: "team1", name: "Platform", timeZone: "Europe/Berlin", yourRole: "lead" };
const roster = [
  { personId: "p1", email: "lea@example.com", role: "lead", since: 1767571200000 },
  { personId: "p2", email: "max@example.com", role: "member", since: 1770000000000 },
];
const detail = { team, roster, may: { update: true, manageLeads: true, manageMembers: true, managePulses: true, viewResults: true } };
const cadence = { _tag: "Weekly", day: "monday", time: "09:00" };
const q = (id, text, hasAnswers) => ({ questionId: id, versionId: id + ".1", templateKey: null, text, dimension: "workload", type: { _tag: "Rating", lowLabel: "Low", highLabel: "High", comment: true }, hasAnswers, estimatedSeconds: 10 });
