const pulse = () => ({ id: "pulse1", team, settings: { name: "Weekly check-in", cadence, answerWindowDays: 2, reminders: 1, anonymityMode: "anonymous", distribution: "invitation" }, questions, estimatedSeconds: questions.length * 10, warnings: [], templateQuestions: [] });
const types = { ".html": "text/html", ".js": "text/javascript", ".css": "text/css" };
const json = (res, status, body) => { res.writeHead(status, { "content-type": "application/json" }); res.end(JSON.stringify(body)); };
createServer(async (req, res) => {
  const url = new URL(req.url, "http://x");
  let body = ""; for await (const chunk of req) body += chunk;
  if (url.pathname.startsWith("/api/") || url.pathname.startsWith("/auth/")) calls.push(`${req.method} ${url.pathname} ${body}`);
  if (url.pathname === "/__calls") return json(res, 200, calls);
  if (url.pathname === "/auth/login") { res.writeHead(302, { location: "https://example.authkit.app/" }); return res.end(); }
  if (url.pathname === "/auth/session") return signedIn ? json(res, 200, { _tag: "SignedIn", organization: { id: "org1", name: "Acme" }, personId: "p1", organizationAdmin: true }) : json(res, 401, { _tag: "Unauthenticated" });
  if (url.pathname === "/api/teams" && req.method === "GET") return json(res, 200, [team]);
  if (url.pathname === "/api/teams/team1" && req.method === "GET") return json(res, 200, detail);
  if (url.pathname === "/api/teams/team1/pulses" && req.method === "GET") return json(res, 200, { team, pulses: [{ id: "pulse1", name: "Weekly check-in", cadence, questionCount: questions.length, estimatedSeconds: 20 }] });
  if (url.pathname === "/api/teams/team1/pulses/pulse1" && req.method === "GET") return json(res, 200, pulse());
  if (url.pathname === "/api/teams/team1/pulses/pulse1/order" && req.method === "PUT") {
    const order = JSON.parse(body).order; questions = order.map((id) => questions.find((x) => x.questionId === id)); return json(res, 200, pulse());
  }
  if (url.pathname === "/api/organization" && req.method === "GET") return json(res, 200, { name: "Acme", minimumGroupSize: 4, people: [{ personId: "p1", email: "lea@example.com", organizationAdmin: true, linked: true }] });
  if (url.pathname.startsWith("/api/")) return json(res, 500, {});
  let file = url.pathname === "/answer" ? "/answer.html" : url.pathname;
  try { const data = await readFile(join(dist, file)); res.writeHead(200, { "content-type": types[extname(file)] ?? "application/octet-stream" }); return res.end(data); }
  catch { const data = await readFile(join(dist, "index.html")); res.writeHead(200, { "content-type": "text/html" }); return res.end(data); }
}).listen(port);
